def unit_of_work(metadata=None, timeout=None):
    """
    Decorator that wraps a transaction function to run it inside a Neo4j transaction
    with optional metadata and timeout configuration.

    The wrapped transaction function must accept a single argument: the transaction
    object.  The decorator transforms it into a function that expects a session
    instance as its first argument and automatically manages the transaction
    lifecycle (begin, commit, rollback).
    """
    from functools import wraps

    # Validate decorator arguments
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dict or None")
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number or None")
        if timeout < 0:
            raise ValueError("timeout must not be negative")

    def decorator(func):
        @wraps(func)
        def wrapper(session, *args, **kwargs):
            """
            Wrapper that runs the transaction function inside a transaction.
            :param session: Neo4j session object.
            """
            # Ensure session can begin a transaction
            if not hasattr(session, "begin_transaction"):
                raise TypeError(
                    "The first argument must be a Neo4j session object "
                    "with a 'begin_transaction' method."
                )

            # Build transaction configuration
            tx_config = {}
            if timeout is not None:
                tx_config["timeout"] = timeout
            if metadata is not None:
                tx_config["metadata"] = metadata

            tx = session.begin_transaction(**tx_config)
            try:
                result = func(tx, *args, **kwargs)
            except Exception:
                try:
                    tx.rollback()
                except Exception:
                    # Ignore rollback errors
                    pass
                raise
            else:
                tx.commit()
                return result

        return wrapper

    return decorator<|return|>

