            return [value for _, value in iterable]

        # Build the full list of values for indexing
        if data_mapping is not None:
            all_values = _values_from_mapping(data_mapping)
        else:
            all_values = _values_from_iterable(data_iterable)

        # If no specific keys/indexes requested, return all values
        if not keys:
