    if not keys:
        if field_names is None:
            # We cannot determine the fields; return an empty dict.
            return {}
        return {name: _get_value(name) for name in field_names}

    result = {}
    for k in keys:
        if isinstance(k, int):
            # Index-based selection
            try:
                name = field_names[k]
            except Exception as exc:
                # Provide a more specific IndexError as required.
                raise IndexError(f"Index {k} out of bounds") from None
            result[name] = _get_value(name)
        else:
            # Name-based selection
            # For names not present in the record, use None.
            name = k
            result[name] = _get_value(name)
