    def _chunk_args(args: Sequence[str]) -> list[list[str]]:
        chunks: list[list[str]] = []
        current: list[str] = []
        # Initial length includes the command itself and the separating spaces
        current_len = sum(len(part) for part in cmd) + len(cmd) + 1  # spaces between parts
        for arg in args:
            # Estimate length with an added space
            additional = len(arg) + 1
            if current_len + additional > _max_length:
                if current:
                    chunks.append(current)
                current = [arg]
                current_len = sum(len(part) for part in cmd) + len(cmd) + 1 + additional
            else:
                current.append(arg)
                current_len += additional
        if current:
            chunks.append(current)
        return chunks

    chunks = _chunk_args(varargs)

    # Runner for a single chunk
    def _run_chunk(chunk: list[str]) -> tuple[int, bytes]:
        try:
            result = subprocess.run(
                cmd + tuple(chunk),
                capture_output=True,
                **kwargs
            )
            return result.returncode, result.stdout
        except Exception as exc:
            # On error, treat as non-zero exit and capture exception message
            return 1, str(exc).encode()

    # If concurrency is 1, just run sequentially
    if target_concurrency == 1:
        results = [_run_chunk(chunk) for chunk in chunks]
    else:
        import concurrent.futures
        results: list[tuple[int, bytes]] = [(-1, b'')] * len(chunks)
        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            future_to_idx = {executor.submit(_run_chunk, c): i for i, c in enumerate(chunks)}
            for future in concurrent.futures.as_completed(future_to_idx):
                idx = future_to_idx[future]
                try:
                    rc, out = future.result()
                except Exception as exc:
                    rc, out = 1, str(exc).encode()
                results[idx] = (rc, out)

    # Aggregate return code and output
    overall_rc = max(rc for rc, _ in results) if results else 0
