def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise TypeError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl <= 0:
        raise ValueError("ttl must be a positive number")
    if not callable(timer):
        raise TypeError("timer must be callable returning a monotonic time")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def _make_key(args, kwds, typed):
        """Build a hashable key from function arguments."""
        # start with positional args
        key = args
        # include keyword args sorted by key name
        if kwds:
            kw_items = tuple(sorted(kwds.items()))
            key += kw_items
        # if typed, prepend the type of each argument value
        if typed:
            try:
                key = tuple((type(a), a) for a in key)
            except TypeError as exc:
                raise TypeError(f"unhashable argument with typed=True: {exc}") from exc
        return key

    def decorator(func):
        cache = collections.OrderedDict()
        hits = 0
        misses = 0

        @functools.wraps(func)
        def wrapper(*args, **kwds):
            nonlocal hits, misses
            try:
                key = _make_key(args, kwds, typed)
            except Exception:
                # If key generation fails, fall back to no caching
                return func(*args, **kwds)

            now = None
            try:
                now = timer()
            except Exception:
                now = time.monotonic()

            # Check cache
            try:
                expires_at, value = cache[key]
                if now < expires_at:
                    hits += 1
                    return value
                else:
                    # expired entry
                    del cache[key]
            except KeyError:
                pass

            # Compute value
            value = func(*args, **kwds)
            expires_at = now + ttl
            cache[key] = (expires_at, value)
            # Enforce LRU order: move to end
            cache.move_to_end(key, last=True)
            if len(cache) > maxsize:
                cache.popitem(last=False)  # pop least-recently-used
            misses += 1
            return value

        def cache_info():
            """Return cache statistics."""
            return functools._lru_cache_wrapper._CacheInfo(
                hits, misses, maxsize, len(cache)
            )

        def cache_clear():
            """Clear the cache and statistics."""
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator
