    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non‑negative integer")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise ValueError("ttl must be a non‑negative number")
    if not callable(timer):
        raise TypeError("timer must be callable")

    def decorator(func):
        cache = {}
        order = []

        def make_key(args, kwargs):
            """Create a key from args and kwargs respecting the typed flag."""
            if typed:
                key = tuple((arg, type(arg)) for arg in args)
            else:
                key = args
            if kwargs:
                # sort kwargs to ensure deterministic order
                items = tuple(sorted(kwargs.items()))
                if typed:
                    items = tuple((k, v, type(v)) for k, v in items)
                key += items
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
