                else:
                    # expired entry
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    del cache[key]
            # Compute the function, handle exceptions without caching
            try:
                result = func(*args, **kwargs)
            except Exception:
                raise
            # Store the result with the current timestamp
            cache[key] = (result, now)
            order.append(key)
            if len(cache) > maxsize:
                # Evict least recently used item
                oldest = order.pop(0)
                cache.pop(oldest, None)
