    """
    Format an exception into a readable string.
    """
    # Validate parameters
    try:
        max_level = int(max_level)
        if max_level <= 0:
            max_level = 30
    except Exception:
        max_level = 30
    try:
        max_path_level = int(max_path_level)
        if max_path_level <= 0:
            max_path_level = 5
    except Exception:
        max_path_level = 5

    # If e is not an exception instance, just return its string representation
    if not isinstance(e, BaseException):
        return str(e)

    try:
        import traceback
        import os

        # Extract traceback frames; if no trace, just show the exception
        tb = e.__traceback__
        frames = traceback.extract_tb(tb) if tb else []
        if not frames:
            return f"{type(e).__name__}: {e}"

        # Keep only the last max_level frames (most recent)
        frames = frames[-max_level:]

        # Build a formatted string for each frame
        formatted_frames = []
        for frm in frames:
            # Normalize the path and limit the depth
            path = os.path.normpath(frm.filename)
            parts = path.split(os.sep)
            if len(parts) > max_path_level:
                parts = parts[-max_path_level:]
                path = os.sep.join(parts)

            location = f'  File "{path}", line {frm.lineno}, in {frm.name}'
            code_line = f"    {frm.line}" if frm.line else ""
            formatted_frames.append(f"{location}\n{code_line}".rstrip())

        # Combine exception info and stack trace
        header = f"{type(e).__name__}: {e}"
        return header + "\n" + "\n".join(formatted_frames)

    except Exception:
        # Fallback: simple string representation if anything goes wrong
        return str(e)<|return|>

