def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        import sys
    except Exception:
        # If import fails, conservatively do not attempt C optimizations
        return False

    # Detect PyPy: prefer sys.implementation.name, fallback to sys.version sniffing
    if hasattr(sys, "implementation"):
        if getattr(sys.implementation, "name", "").lower() == "pypy":
            return False
    else:  # pragma: no cover
        if "pypy" in sys.version.lower():
            return False

    # Check the PURE_PYTHON environment variable
    pure_python_val = os.getenv("PURE_PYTHON")
    if pure_python_val is None:
        return True

    # Normalize the value to decide truthiness
    truthy_values = {"1", "true", "yes", "y", "t"}
    # Convert to lower-case for comparison; strip whitespace
    if pure_python_val.strip().lower() in truthy_values:
        return False
    # Any other value implies we should attempt C optimizations
    return True<|return|>

