    err_map = getattr(self, "_err_indices", None)
    if isinstance(err_map, dict):
        if coord_name in err_map:
            return err_map[coord_name]

    # Next look for an attribute named ``{coord_name}_err``.
    err_attr_name = f"{coord_name}_err"
    try:
        err_vals = getattr(self, err_attr_name)
    except AttributeError:
        raise AttributeError(f"No error data found for coordinate '{coord_name}'")

    # Attempt to get indices of non‑zero, non‑None entries.
    try:
        # If we have a NumPy array, use .nonzero().
        if hasattr(err_vals, "nonzero"):
            return list(err_vals.nonzero()[0])
    except Exception:
        pass

    # Otherwise assume a sequence that we can iterate over.
    try:
        indices = [i for i, v in enumerate(err_vals)
                   if v is not None and v != 0]
        return indices
    except TypeError:
        # err_vals is not iterable. Treat it as a scalar.
        return [0] if err_vals not in (None, 0) else []

