def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z" (this corresponds
    to first three coordinates, if they are present), which allows to
    simplify plotting. Existing values are not removed from
    *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example, in :class:`.ToCSV`).
    """
    # Retrieve current error context, if any
    try:
        err_ctx = getattr(context, "error", None)
        if err_ctx is None:
            # context might be a plain dict
            err_ctx = context.get("error", {}) if isinstance(context, dict) else {}
        if not isinstance(err_ctx, dict):
            err_ctx = {}
    except Exception:
        err_ctx = {}

    # Helper to add an error entry
    def _add_err(key, idx):
        if key in err_ctx:
            entry = err_ctx[key]
            # Keep a list of indices if multiple occur
            if isinstance(entry, dict):
                if "index" in entry and "indices" not in entry:
                    # Convert to list format
                    err_ctx[key] = {"indices": [entry["index"], idx]}
                elif "indices" in entry:
                    entry["indices"].append(idx)
                else:
                    err_ctx[key] = {"indices": [idx]}
            else:
                # Unexpected format, overwrite
                err_ctx[key] = {"indices": [idx]}
        else:
            err_ctx[key] = {"index": idx}

    # Determine mapping of coordinate letter to field index
    # Assume first three fields map to x, y, z in order
    coord_map = {}
    fields = getattr(self, "_field_names", getattr(self, "fields", []))
    for i, fname in enumerate(fields[:3]):
        coord_map[fname] = chr(ord('x') + i)  # map field name to 'x','y','z'

    # Inspect all attributes that look like error definitions
    for attr in dir(self):
        if not attr.startswith("error_"):
            continue
        if not ("_low" in attr or "_high" in attr):
            continue
        parts = attr.split("_")
        if len(parts) < 3:
            continue

        # The coordinate part (e.g., 'E' in 'error_E_low')
        coord_part = parts[1]
        lowhigh = parts[2]
        # Map coordinate part to 'x','y','z' if possible, otherwise use original
        coord_name = coord_map.get(coord_part, coord_part.lower()[:1])

        err_key = f"{coord_name}_{lowhigh}"

        # Determine the index of the original field that this error refers to
        # We assume the field name just before the error suffix is the base field
        base_field = coord_part  # crude assumption
        try:
            base_index = getattr(self, "_field_indices", {}).get(base_field)
            if base_index is None:
                # Try to find index by field name list
                base_index = fields.index(base_field) if base_field in fields else None
            if base_index is None:
                continue
        except (AttributeError, ValueError):
            continue

        _add_err(err_key, base_index)

    # Write back the updated error context
    try:
        if hasattr(context, "error"):
            context.error = err_ctx
        elif isinstance(context, dict):
            context["error"] = err_ctx
    except Exception:
        # Silently ignore update failures; context update is optional
        pass
