def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation of inputs
    try:
        bins_iter = list(bins)
        edges_iter = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable sequences")

    if len(edges_iter) != len(bins_iter) + 1:
        raise ValueError(
            f"Length mismatch: edges must have one more element "
            f"than bins (got {len(edges_iter)} vs {len(bins_iter)})"
        )

    integral_value = 0.0
    # Compute the sum of bin values multiplied by their bin widths
    try:
        for bin_val, left_edge, right_edge in zip(bins_iter, edges_iter[:-1], edges_iter[1:]):
            width = right_edge - left_edge
            integral_value += bin_val * width
    except TypeError as exc:
        raise TypeError(f"Non-numeric data encountered during integration: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error during integration: {exc}") from exc

    return integral_value
<|return|>

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np
    try:
        bins_arr = np.asarray(bins, dtype=float)
        edges_arr = np.asarray(edges, dtype=float)
    except Exception as exc:
        raise ValueError("bins and edges must be array-like") from exc

    if bins_arr.ndim != 1:
        raise ValueError("bins must be a 1-D sequence")
    if edges_arr.ndim != 1:
        raise ValueError("edges must be a 1-D sequence")
    if len(edges_arr) != len(bins_arr) + 1:
        raise ValueError("edges length must be len(bins) + 1")

    widths = np.diff(edges_arr)
    return float(np.sum(bins_arr * widths))<|return|>

