    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
        add keyword argument *level*.
    """
    # Validate input types
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")

    # Normalize level: -1 means unlimited recursion, otherwise must be positive integer
    if level != -1 and (not isinstance(level, int) or level < 1):
        raise ValueError("level must be -1 or a positive integer")

    def _difference_recursive(a, b, remaining_depth):
        """Recursively compute the difference between two dictionaries."""
        result = {}
        for key, val in a.items():
            if key not in b:
                # Key only in a: include it
                result[key] = val
            else:
                other = b[key]
                if isinstance(val, dict) and isinstance(other, dict):
                    # Both values are dicts – recurse if depth allows
                    if remaining_depth == 0:
                        # Depth exhausted: treat as different if contents differ
                        if val != other:
                            result[key] = val
                    else:
                        # Recurse with decremented depth for positive limits
                        next_depth = remaining_depth - 1 if remaining_depth > 0 else -1
                        subdiff = _difference_recursive(val, other, next_depth)
                        if subdiff:
                            result[key] = subdiff
                else:
                    # For non-dict values, include if they differ
                    if val != other:
                        result[key] = val
        return result

    return _difference_recursive(d1, d2, level)
