def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        coord_arr = np.asarray(coord)
    except Exception as exc:
        raise ValueError("Coordinate must be array-like.") from exc

    if coord_arr.ndim != 1:
        raise ValueError("Coordinate must be a 1D array of length equal to histogram dimensionality.")

    if not hasattr(self, "edges"):
        raise AttributeError("Histogram object does not have 'edges' attribute.")

    if len(coord_arr) != len(self.edges):
        raise ValueError(f"Coordinate dimension ({len(coord_arr)}) does not match histogram dimensionality ({len(self.edges)}).")

    # Check bounds for each dimension
    for i, (c, edges) in enumerate(zip(coord_arr, self.edges)):
        if c < edges[0] or c >= edges[-1]:
            # Outside edges - ignore
            return

    # Find bin indices
    bin_indices = []
    for c, edges in zip(coord_arr, self.edges):
        # Use right side to get the lower bin index
        idx = np.searchsorted(edges, c, side="right") - 1
        if idx < 0 or idx >= len(edges) - 1:
            # Bin not found (should not happen due to earlier check)
            return
        bin_indices.append(idx)

    # Convert to tuple for indexing
    bin_tuple = tuple(bin_indices)

    # Ensure the data array exists
    if not hasattr(self, "data"):
        raise AttributeError("Histogram object does not have 'data' attribute.")

    try:
        weight_val = float(weight)
    except Exception as exc:
        raise ValueError("Weight must be a numeric value.") from exc

    # Update bin content
    self.data[bin_tuple] += weight_val

    # Update optional statistics
    if hasattr(self, "entries"):
        self.entries += weight_val
    else:
        self.entries = weight_val
    if hasattr(self, "total_weight"):
        self.total_weight += weight_val
    else:
        self.total_weight = weight_val
    return

