        """
        try:
            # Ensure coordinate is array-like with correct dimensionality
            if isinstance(coord, (list, tuple)):
                if len(coord) != len(self._edges):
                    raise ValueError(
                        f"Coordinate dimension ({len(coord)}) does not match histogram "
                        f"dimension ({len(self._edges)})."
                    )
                coord_arr = np.array(coord, dtype=float)
            elif isinstance(coord, np.ndarray):
                coord_arr = coord
                if coord_arr.ndim == 0:
                    coord_arr = coord_arr.reshape(1)
            else:
                raise TypeError("coord must be a sequence or numpy array")

            # Validate dimensionality
            if coord_arr.ndim != 1 or coord_arr.size != len(self._edges):
                raise ValueError(
                    f"Coordinate must be a 1‑D array of length {len(self._edges)}."
                )

            idxs = []
            for dim, edges in enumerate(self._edges):
                val = float(coord_arr[dim])

                # Edges should be a 1‑D numpy array
                if edges.ndim != 1:
                    raise ValueError(f"Edges for dimension {dim} are not 1‑D.")

                low = edges[0]
                high = edges[-1]

                # Outside histogram bounds? Ignore
                if val < low or val >= high:
                    return

                # Find bin index (left‑inclusive, right‑exclusive)
                bin_idx = np.searchsorted(edges, val, side="right") - 1
                idxs.append(int(bin_idx))

            # Increment the appropriate histogram bin
            self._bins[tuple(idxs)] += weight

        except Exception as exc:
            # Wrap any unexpected issue in a RuntimeError for consistency
            raise RuntimeError(f"Failed to fill histogram: {exc}") from exc<|return|>

