def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    from re import Pattern

    # Assume compiled regex patterns are defined elsewhere in the module
    # If not found, we fall back to permissive patterns to avoid breaking the function.
    try:
        key_regex: Pattern = _label_key_regex
    except NameError:
        # Fallback: any non-empty string
        import re  # noqa: F401
        key_regex = re.compile(r'.+')

    try:
        value_regex: Pattern = _label_value_regex
    except NameError:
        import re  # noqa: F401
        value_regex = re.compile(r'.*')

    errors = []

    if not isinstance(labels, dict):
        raise ValidationError(
            messages=[{"labels": "Labels must be a dictionary"}]
        )

    for key, val in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append(
                {str(key): "expected string or bytes-like object"}
            )
        else:
            # Validate key regex
            if not key_regex.fullmatch(key):
                errors.append(
                    {
                        key: (
                            f"Label key '{key}' does not match the regex "
                            f"{key_regex.pattern}"
                        )
                    }
                )

        # Validate value type
        if isinstance(val, (list, tuple, set, dict)):
            # Entire value examined as non-string
            errors.append(
                {str(val): "expected string or bytes-like object"}
            )
        elif not isinstance(val, (str, bytes)):
            errors.append(
                {str(val): "expected string or bytes-like object"}
            )
        else:
            # Validate value regex
            if not value_regex.fullmatch(val):
                errors.append(
                    {
                        val: (
                            f"Label value '{val}' does not match the regex "
                            f"{value_regex.pattern}"
                        )
                    }
