    if errors:
        raise ValidationError(messages=errors)<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Regular expression for Azure resource tags (keys and values).
    _REGEX_KEY = re.compile(r"^[a-z0-9]([-a-z0-9._]{0,61}[a-z0-9])?$")
    _REGEX_VALUE = re.compile(r"^[a-z0-9]([-a-z0-9._]{0,61}[a-z0-9])?$")

    errors = []

    if not isinstance(labels, dict):
        errors.append({"labels": "labels must be a dict"})
        raise ValidationError(errors)

    for key, value in labels.items():
        # ---------- label key ----------
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
            continue
        if isinstance(key, bytes):
            key_str = key.decode("utf-8", errors="ignore")
        else:
            key_str = key
        if not _REGEX_KEY.match(key_str):
            errors.append(
                {
                    key_str: f"Label key '{key_str}' does not match the regex [...]."
                }
            )

        # ---------- label value ----------
        # Azure tags support only string values; nested lists/tuples are invalid.
        if isinstance(value, (list, tuple)):
            errors.append({str(value): "expected string or bytes-like object"})
            continue
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
            continue
        if isinstance(value, bytes):
            value_str = value.decode("utf-8", errors="ignore")
        else:
            value_str = value
        if not _REGEX_VALUE.match(value_str):
            errors.append(
                {
                    value_str: f"Label value '{value_str}' does not match the regex [...]."
                }
            )

    if errors:
        raise ValidationError(errors)<|return|>

