    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    class ValidationError(ValueError):
        """Raised when validation fails."""
        pass

    if not isinstance(value, str):
        raise ValidationError("Value must be a string")

    import re

    # Define some common regex patterns
    patterns = {
        "email": r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$",
        "url": r"^(https?://)?([A-Za-z0-9.-]+)(:[0-9]+)?(/[^\s]*)?$",
        "phone": r"^\+?(\d{1,3})?[-.\s]?(\(?\d{3}\)?)[-.\s]?\d{3}[-.\s]?\d{4}$",
        "zip": r"^\d{5}(-\d{4})?$",
    }

    # Detect which pattern to use based on simple heuristics
    detected = None
    if "@" in value and re.search(r"\.[A-Za-z]{2,}$", value):
        detected = "email"
    elif re.match(r"^(https?://)", value) or re.match(r"^[A-Za-z0-9.-]+\.[A-Za-z]{2,}(/.*)?$", value):
        detected = "url"
    elif re.match(r"^\+?(\d{1,3})?[-.\s]?", value):
        # Basic phone number heuristic
        detected = "phone"
    elif re.match(r"^\d{5}(-\d{4})?$", value):
        detected = "zip"

    if not detected:
        raise ValidationError("Could not determine a suitable pattern for validation")

    pattern = patterns[detected]
    try:
        if not re.fullmatch(pattern, value):
            raise ValidationError(f"Value does not match the expected {detected} pattern")
    except re.error as e:
        raise ValidationError(f"Invalid regular expression: {e}") from e

    # If we reach this point, validation succeeded (no return needed)<|return|>

