def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    Identifying fields are defined as the set ``{'apiVersion', 'kind', 'metadata'}``
    and are kept unmodified; all other scalar values are replaced by ``None``.
    Lists are processed element‑wise: dictionary elements are recursed into, while
    non‑dictionary elements are replaced by ``None``.
    """

    # Validate input type
    if not isinstance(manifest_dict, dict):
        raise TypeError(
            f"manifest_dict must be a dict, got {type(manifest_dict).__name__}"
        )

    # Define identifying keys that are preserved when first_level is True.
    identifying_keys = {"apiVersion", "kind", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            try:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
            except Exception as exc:
                # Preserve core logic but include context on failure
                raise ValueError(f"Error processing nested dict at key '{key}': {exc}") from exc
        elif isinstance(value, list):
            # Process list elements individually
            processed_list = []
            for idx, elem in enumerate(value):
                if isinstance(elem, dict):
                    try:
                        processed_list.append(
                            generate_default_observer_schema_dict(elem, first_level=False)
                        )
                    except Exception as exc:
                        raise ValueError(
                            f"Error processing dict element {idx} in list at key '{key}': {exc}"
                        ) from exc
                else:
                    processed_list.append(None)
            result[key] = processed_list
        else:
            # Scalar values are replaced with None unless identified and top-level
            if first_level and key in identifying_keys:
                result[key] = value
            else:
                result[key] = None

