    ------
    KeyError
        If an observed field is missing from ``response``.
    """
    # Defensive checks: all arguments must be dictionaries.
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            f"last_applied_manifest must be a dict, got {type(last_applied_manifest)!r}"
        )
    if not isinstance(observer_schema, dict):
        raise TypeError(
            f"observer_schema must be a dict, got {type(observer_schema)!r}"
        )
    if not isinstance(response, dict):
        raise TypeError(
            f"response must be a dict, got {type(response)!r}"
        )
    for field, sub_schema in observer_schema.items():
        if field not in response:
            raise KeyError(
                f"Observed field '{field}' not present in the Kubernetes response"
            )
        # If the sub-schema is a dict, we recurse.
        if isinstance(sub_schema, dict):
            # Ensure the target field exists and is a dict
            if field not in last_applied_manifest or not isinstance(
                last_applied_manifest[field], dict
