    if not hasattr(spec, "manifest"):
        raise AttributeError("Application spec has no 'manifest' attribute")
    if not hasattr(spec, "observer_schema"):
        raise AttributeError("Application spec has no 'observer_schema' attribute")

    manifest = spec.manifest
    observer_schema = spec.observer_schema

