def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Defensive checks for the app object and its attributes
    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            return {}
        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            return {}
    except Exception as exc:
        # In case app structure is somehow unexpected
        raise ValueError(f"Invalid application structure: {exc}") from exc

    # Ensure that the observer_schema attribute exists and is a dict
    observer_schema = getattr(spec, "observer_schema", None)
    if observer_schema is None:
        observer_schema = {}
    elif not isinstance(observer_schema, dict):
        raise TypeError("The 'observer_schema' attribute must be a dict if provided.")

    # Store the defaults we are going to add
    added_defaults = {}

    # Iterate over each resource in the manifest and add a default schema
    # if it is missing in the custom observer schema.
    # We consider the key for each resource to be a combination of its apiVersion
    # and kind to avoid collisions between different API groups.
    for idx, resource in enumerate(manifest):
        if not isinstance(resource, dict):
            # Skip entries that are not dict-like
            continue

        api_version = resource.get("apiVersion")
        kind = resource.get("kind")

        # Build a unique key to use in the observer schema dictionary.
        # If either part is missing, fall back to a generic key that includes the index.
        if api_version and kind:
            key = f"{api_version}_{kind}"
        else:
            key = f"resource_{idx}"

        # Only add a default if a custom config is absent
        if key not in observer_schema:
            # Create a shallow copy to avoid mutating the original resource
            try:
                default_entry = dict(resource)
            except Exception:
                # If the resource cannot be copied, skip adding
                continue

            # In many cases, the default obs schema only includes the metadata field
            # to allow for basic display and filtering. If metadata is missing,
            # we still store the whole resource.
            metadata = default_entry.get("metadata", {})
            if metadata:
                # Keep only name and namespace for the default observer output
                default_schema_part = {
                    "metadata": {
                        "name": metadata.get("name"),
                        "namespace": metadata.get("namespace"),
                    }
                }
            else:
                # No metadata; keep the entire resource
                default_schema_part = default_entry

            added_defaults[key] = default_schema_part

    # Merge the newly created defaults into the existing observer_schema
    observer_schema.update(added_defaults)

    # Set the updated schema back onto the spec (in case it was initially None)
    setattr(spec, "observer_schema", observer_schema)

    # Return the newly added defaults for reference
    return added_defaults

