def format(
    self,
    sql: 'AnyStr',
    params: 'Union[Dict[Union[str, int], Any], Sequence[Any]]',
) -> 'Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]':

    # Basic validation
    if sql is None:
        raise ValueError("sql must not be None")
    if params is None:
        raise ValueError("params must not be None")

    # Preserve byte or string type
    is_bytes = isinstance(sql, bytes)
    try:
        sql_text = sql.decode() if is_bytes else sql
    except Exception as exc:
        raise ValueError("sql must be a string or bytes") from exc

    # Determine styles
    in_style = getattr(self, "in_style", None)
    out_style = getattr(self, "out_style", None)
    if in_style is None or out_style is None:
        raise AttributeError("self must have 'in_style' and 'out_style' attributes")

    # If styles are already equal, return unchanged
    if in_style == out_style:
        return (sql, params)

    # Define regex for placeholder detection based on in_style
    if in_style == "qmark":
        pattern = r"\?"
    elif in_style == "named":
        pattern = r"(:[a-zA-Z_][a-zA-Z0-9_]*|@[a-zA-Z_][a-zA-Z0-9_]*)"
    elif in_style == "numeric":
        pattern = r":(\d+)"
    elif in_style == "format":
        # treat %(s) or %(d) etc
        pattern = r"%\([a-zA-Z_][a-zA-Z0-9_]*\)[sd]"
    else:
        # fallback: treat '?' but warn
        pattern = r"\?"

    # Prepare param iterator
    if isinstance(params, Mapping):
        # Preserve order of keys as they appear
        param_iter = iter(params.keys())
        param_values = params
        is_mapping = True
    else:
        # sequence
        param_iter = iter(range(len(params)))
        param_values = list(params)
        is_mapping = False

    new_params_dict = OrderedDict()
    new_params_list = []

    # Helper to get next param index/name
    def next_param():
        try:
            idx = next(param_iter)
            return idx
        except StopIteration:
            raise ValueError("More placeholders in sql than provided params") from None

    # Build new sql by scanning placeholders
    def repl(match):
        placeholder = match.group(0)
        token = next_param()
        if out_style == "qmark":
            new_placeholder = "?"
            if is_mapping:
                new_params_dict[token] = param_values[token]
            else:
                new_params_list.append(param_values[token])
        elif out_style == "named":
            if is_mapping:
                new_placeholder = f":{token}"
                new_params_dict[token] = param_values[token]
            else:
                name = f"param{token}"
                new_placeholder = f":{name}"
                new_params_dict[name] = param_values[token]
        elif out_style == "numeric":
            new_placeholder = f":{token+1 if not is_mapping else token}"
            if is_mapping:
                new_params_dict[token] = param_values[token]
            else:
                new_params_list.append(param_values[token])
        elif out_style == "format":
            new_placeholder = "%s"
            if is_mapping:
                new_params_dict[token] = param_values[token]
            else:
                new_params_list.append(param_values[token])
        else:
            # Unknown out style; keep original placeholder
            new_placeholder = placeholder
            if is_mapping:
                new_params_dict[token] = param_values[token]
            else:
                new_params_list.append(param_values[token])
        return new_placeholder

    try:
        new_sql_text = re.sub(pattern, repl, sql_text)
    except Exception as exc:
        raise RuntimeError("Failed to reformat SQL") from exc

    # Build converted params
    converted_params: Any
    if is_mapping:
        converted_params = dict(new_params_dict)
    else:
        converted_params = new_params_list

    # Restore original type
    result_sql: AnyStr = new_sql_text.encode() if is_bytes else new_sql_text
    return (result_sql, converted_params)<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

