    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if not isinstance(inventory, dict):
        raise TypeError(f"Expected inventory to be dict, got {type(inventory).__name__}")

    # Attempt to extract spec version from the "type" field if requested
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Attempt to parse a simple "X.Y" version pattern
            import re
            match = re.fullmatch(r'(\d+)\.(\d+)', type_val.strip())
            if match:
                self.spec_version = f"{match.group(1)}.{match.group(2)}"
        # If extraction fails, keep existing self.spec_version

    # Basic required keys for an inventory may vary, but we enforce at least "name" and "components".
    required_keys = ["name", "components"]
    missing = [k for k in required_keys if k not in inventory]
    if missing:
        raise KeyError(f"Missing required inventory keys: {', '.join(missing)}")

    # Ensure components is a list or dict
    components = inventory["components"]
    if not isinstance(components, (list, dict)):
        raise TypeError(f"'components' must be a list or dict, got {type(components).__name__}")

    # Optional: validate that each component has a 'name' field
    if isinstance(components, list):
        for idx, comp in enumerate(components):
            if not isinstance(comp, dict):
                raise TypeError(f"Component at index {idx} must be dict, got {type(comp).__name__}")
            if "name" not in comp:
                raise KeyError(f"Component at index {idx} missing 'name' key")

    # If spec_version is set we can apply a minimal format check
    if hasattr(self, "spec_version"):
        if not isinstance(self.spec_version, str):
            raise TypeError(f"spec_version must be a string, got {type(self.spec_version).__name__}")
        if not re.fullmatch(r'\d+\.\d+', self.spec_version):
            raise ValueError(f"spec_version '{self.spec_version}' is not in the expected 'X.Y' format")

    return True

