    Returns True if the inventory passes all validation checks, otherwise raises
    ValueError with a descriptive message.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")

    # Extract spec version if requested
    if extract_spec_version:
        type_value = inventory.get('type')
        if isinstance(type_value, str):
            # Attempt to find a version-like pattern in the type string
            parts = type_value.replace(',', ' ').split()
            for part in parts:
                # Accept patterns like '1.0', 'v1.0', 'spec_2.1'
                cleaned = part.lstrip('vV').replace('spec_', '').replace('spec', '')
                if cleaned.replace('.', '', 1).isdigit():
                    self.spec_version = cleaned
                    break
        # If extraction failed, keep existing self.spec_version

    # Validate required top-level keys
    required_keys = ['name', 'components']
    for key in required_keys:
        if key not in inventory:
            raise ValueError(f"Missing required key in inventory: '{key}'.")

    # Validate components list
    components = inventory.get('components')
    if not isinstance(components, list):
        raise ValueError("The 'components' key must be a list.")

    for idx, component in enumerate(components):
        if not isinstance(component, dict):
            raise ValueError(f"Component at index {idx} must be a dictionary.")

        # Ensure each component has required fields
        comp_required = ['id', 'type', 'status']
        for ckey in comp_required:
            if ckey not in component:
                raise ValueError(
                    f"Component at index {idx} is missing required field: '{ckey}'."
                )

        # Basic type validations for each field
        if not isinstance(component['id'], (str, int)):
            raise ValueError(
                f"Component 'id' at index {idx} must be a string or integer."
            )
        if not isinstance(component['type'], str):
            raise ValueError(
                f"Component 'type' at index {idx} must be a string."
            )
        if component['status'] not in ('active', 'inactive'):
            raise ValueError(
                f"Component 'status' at index {idx} must be 'active' or 'inactive'."
            )

    # Validate spec_version against known values if set
    known_versions = {'1.0', '1.1', '2.0'}
    if self.spec_version and self.spec_version not in known_versions:
        raise ValueError(f"Unsupported spec_version '{self.spec_version}'.")
    # If spec_version is None, accept it as a placeholder; external logic may handle it.

    # If all checks pass, return True
    return True<|return|>

