def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input digests_used
    try:
        digests_used_set = set(digests_used)
    except TypeError as exc:
        raise ValueError("digests_used must be an iterable of digests") from exc

    # Extract digests from manifest_files
    manifest_digests = set()
    if isinstance(manifest_files, dict):
        # Assume keys are digests
        manifest_digests.update(manifest_files.keys())
    else:
        # Assume iterable of entries, each entry expected to have a 'digest' key
        for entry in manifest_files:
            try:
                manifest_digests.add(entry['digest'])
            except (TypeError, KeyError) as exc:
                # Skip malformed entries but keep processing
                continue

    # Check for missing digests (used but not in manifest)
    missing = digests_used_set - manifest_digests
    if missing:
        missing_list = ", ".join(sorted(missing))
        raise ValueError(f"Missing digests in manifest: {missing_list}")

    # Check for unused digests (present in manifest but not needed)
    unused = manifest_digests - digests_used_set
    if unused:
        unused_list = ", ".join(sorted(unused))
        raise ValueError(f"Unreferenced digests in manifest: {unused_list}")

    return True<|return|>

