    # Fall back to common names if the primary ones are not present.
    id_names = ("inventory_id", "id", "inventory_id", "inventoryId")
    ver_names = ("version", "ver", "inventory_version")
    time_names = ("created_at", "timestamp", "createdOn", "created_on")

    try:
        self_id = _get_attr(self, id_names)
        prior_id = _get_attr(prior, id_names)
        self_ver = _get_attr(self, ver_names)
        prior_ver = _get_attr(prior, ver_names)
        self_time = _get_attr(self, time_names)
        prior_time = _get_attr(prior, time_names)
    except AttributeError as exc:
        raise AttributeError(f"Missing required inventory attribute: {exc}") from None

    # IDs must match
    if self_id != prior_id:
        raise ValueError("Inventory IDs do not match between current and prior inventory")

    # Prior must have a lower version number
    try:
        if prior_ver >= self_ver:
            raise ValueError("Prior inventory must have a lower version number")
    except TypeError:
        # If versions are not comparable, fall back to string comparison
        if str(prior_ver) >= str(self_ver):
            raise ValueError("Prior inventory must have a lower version number")

    # Prior must have an earlier timestamp if comparable
    try:
        if type(self_time) != type(prior_time):
            # cannot compare, skip
            pass
        else:
            if prior_time >= self_time:
                raise ValueError("Prior inventory must have an earlier creation timestamp")
    except Exception:
        # In case timestamps are not comparable (e.g., strings), skip
        pass

    # If all checks pass, return True as a confirmation
    return True<|return|>

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same concrete type as self
    if not isinstance(prior, type(self)):
        raise TypeError(
            "prior must be an instance of the same validator class as self"
        )

    def _extract_version(obj):
        """
        Try to get a comparable version indicator from the object.
        Preference order: version, timestamp, modified_at, date.
        If not directly present, look inside an 'inventory' dict.
        """
        # Direct attributes
        for attr in ("version", "timestamp", "modified_at", "date"):
            if hasattr(obj, attr):
                return getattr(obj, attr)
        # Look into inventory dict if available
        inv = getattr(obj, "inventory", None)
        if isinstance(inv, dict):
            for key in ("version", "timestamp", "date"):
                if key in inv:
                    return inv[key]
        return None

    self_val = _extract_version(self)
    prior_val = _extract_version(prior)

    if self_val is None or prior_val is None:
        raise ValueError(
            "Cannot determine version information for either the current or prior inventory"
        )

    # Try a natural comparison; if types differ, fall back to string comparison
    try:
        if prior_val >= self_val:
            raise ValueError(
                f"Prior inventory version ({prior_val}) must be older than current "
                f"inventory version ({self_val})"
            )
    except TypeError:
        # Compare string representations as a last resort
        if str(prior_val) >= str(self_val):
            raise ValueError(
                "Prior inventory version is not older than current inventory (comparison failed)"
            )
    # If no exception was raised, the prior inventory is considered valid
    return None

