def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to convert a version to a sortable tuple of integers
    def _parse_version(v):
        if isinstance(v, (int, float)):
            return (int(v),)
        if isinstance(v, str):
            parts = []
            for part in v.replace('-', '.').split('.'):
                if part.isdigit():
                    parts.append(int(part))
                else:
                    # If non-digit part exists, treat entire string as fallback
                    return (v,)
            return tuple(parts) if parts else (0,)
        # Fallback: use the value as is for comparison
        return (v,)

    # Validate input types
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")
    try:
        target_version = _parse_version(version)
    except Exception as exc:
        raise ValueError(f"Unable to parse version '{version}': {exc}") from exc

    from collections import defaultdict
    result = defaultdict(set)

    # Process each logical path entry in the inventory
    for logical_path, entries in inventory.items():
        if not isinstance(entries, list):
            raise TypeError(f"Inventory entry for '{logical_path}' should be a list, got {type(entries).__name__}")
        for entry in entries:
            if not isinstance(entry, dict):
                raise TypeError(f"Inventory sub-entry should be a dict, got {type(entry).__name__}")
            try:
                entry_version = _parse_version(entry.get('version'))
            except Exception as exc:
                # Skip entries with unparseable version
                continue
            # Include entries with a version less than or equal to the requested one
            if entry_version <= target_version:
                files = entry.get('files')
                if files is None:
                    continue
                if isinstance(files, (list, set, tuple)):
                    for f in files:
                        result[logical_path].add(f)
                else:
                    # Assume single file reference
                    result[logical_path].add(files)

    return dict(result)<|return|>

