def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version not in inventory:
        raise ValueError(f"Version '{version}' not found in inventory")

    logical_map = {}
    found_version = False

    # Iterate over the inventory in insertion order.
    for ver, entries in inventory.items():
        if ver == version:
            found_version = True
        if not found_version:
            continue  # skip entries before the target version

        # Each entry should be a mapping containing at least 'logical_path' and 'content_file'
        if isinstance(entries, (list, tuple)):
            for entry in entries:
                if not isinstance(entry, dict):
                    continue  # skip malformed entries
                logical = entry.get('logical_path')
                file_path = entry.get('content_file')
                if logical is None or file_path is None:
                    continue  # skip incomplete entries
                logical_map.setdefault(logical, set()).add(file_path)
        else:
            # If entries is not a list, treat it as a single entry
            if not isinstance(entries, dict):
                continue
            logical = entries.get('logical_path')
            file_path = entries.get('content_file')
            if logical is None or file_path is None:
                continue
            logical_map.setdefault(logical, set()).add(file_path)

    return logical_map<|return|>

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Basic type checks
        if not isinstance(fixity, dict):
            raise TypeError(f"Expected fixity to be a dict, got {type(fixity).__name__}")

        if 'files' not in fixity:
            raise ValueError("Fixity block must contain a 'files' key")

        files = fixity['files']
        if not isinstance(files, list):
            raise TypeError(f"'files' must be a list, got {type(files).__name__}")

        if not files:
            raise ValueError("'files' list in fixity cannot be empty")

        # Ensure manifest has quick lookup capability
        manifest_set = set(manifest_files)
        seen_paths = set()

        for idx, entry in enumerate(files, start=1):
            if not isinstance(entry, dict):
                raise TypeError(f"Entry {idx} in 'files' must be a dict, got {type(entry).__name__}")

            # Path validation
            if 'path' not in entry:
                raise ValueError(f"Entry {idx} missing required 'path' field")
            path = entry['path']
            if not isinstance(path, str):
                raise TypeError(f"'path' in entry {idx} must be a string, got {type(path).__name__}")

            # Checksum validation
            if 'checksum' not in entry:
                raise ValueError(f"Entry {idx} missing required 'checksum' field")
            checksum = entry['checksum']
            if not isinstance(checksum, str):
                raise TypeError(f"'checksum' in entry {idx} must be a string, got {type(checksum).__name__}")

            # Reference consistency
            if path not in manifest_set:
                raise ValueError(f"File path '{path}' in fixity block not found in manifest")
            if path in seen_paths:
                raise ValueError(f"Duplicate file path '{path}' found in fixity block")
            seen_paths.add(path)<|return|>

