        if not isinstance(fixity["algorithm"], str):
            raise ValueError("Fixity 'algorithm' must be a string")
        if not isinstance(fixity["hash"], str):
            raise ValueError("Fixity 'hash' must be a string")

        # Normalize referenced files
        ref_files = fixity["file"]
        if isinstance(ref_files, str):
            ref_files = [ref_files]
        if not isinstance(ref_files, (list, set, tuple)):
            raise ValueError("Fixity 'file' must be a string or an iterable of strings")

        # Ensure all referenced files exist in manifest
        if not isinstance(manifest_files, (list, set, tuple)):
            raise ValueError("manifest_files must be an iterable of file names")
        manifest_set = set(manifest_files)
        for f in ref_files:
            if f not in manifest_set:
                raise ValueError(f"Fixity references unknown file '{f}' not present in manifest")
    except Exception as exc:
        raise ValueError(f"Invalid fixity block: {exc}") from exc
