def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Path to the source directory or zip file (unused in this implementation).
    xmls : list
        List of XML filenames.
    files : list
        List of all files in the folder or zipfile.

    Returns
    -------
    dict
        key: name of the XML files (without extension)
        value: list of files that share the same basename
    """
    try:
        if xmls is None:
            xmls = []
        if files is None:
            files = []
        if not isinstance(xmls, (list, tuple)):
            raise TypeError("xmls must be a list or tuple of filenames")
        if not isinstance(files, (list, tuple)):
            raise TypeError("files must be a list or tuple of filenames")

        # Build a set of expected basenames from the XML files
        basenames = set()
        for xml_name in xmls:
            if isinstance(xml_name, str):
                base, _ = os.path.splitext(xml_name)
                basenames.add(base)
            else:
                raise TypeError("xmls must contain strings only")

        grouped = {base: [] for base in basenames}

        for file_name in files:
            if not isinstance(file_name, str):
                continue  # skip non-string entries
            base, _ = os.path.splitext(file_name)
            if base in grouped:
                grouped[base].append(file_name)
        return grouped

    except Exception as exc:
        # In case of unexpected errors, return an empty dict
        return {}<|return|>

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    # Validate input type
    if not isinstance(folder, str):
        raise TypeError("folder must be a string representing a path")

    # Import os module dynamically to avoid top‑level import statements
    try:
        os = __import__('os')
    except Exception as exc:
        raise RuntimeError("Failed to import required module 'os'") from exc

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Directory '{folder}' does not exist")

    # First pass: collect base names of XML files
    xml_bases = set()
    try:
        for entry in os.scandir(folder):
            if entry.is_file():
                name, ext = os.path.splitext(entry.name)
                if ext.lower() == ".xml":
                    xml_bases.add(name)
    except Exception as exc:
        raise RuntimeError(f"Error scanning directory '{folder}': {exc}") from exc

    if not xml_bases:
        return {}

    # Second pass: group files that share an XML base
    groups = {base: [] for base in xml_bases}
    try:
        for entry in os.scandir(folder):
            if entry.is_file():
                base, _ = os.path.splitext(entry.name)
                if base in xml_bases:
                    groups[base].append(entry.name)
    except Exception as exc:
        raise RuntimeError(f"Error grouping files in '{folder}': {exc}") from exc

    # Sort each group's file list for deterministic output
    for file_list in groups.values():
        file_list.sort()

    return groups  <|return|>

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo

    Returns
    -------
    dict
        Dicionário com chave ``prefix`` e valor contendo o tipo de arquivo
        ('asset' ou 'rendition') e o caminho do arquivo analisado.
    """
    import os

    # Normaliza o caminho removendo possíveis prefixos de URL
    path = file_path
    if path.lower().startswith("file://"):
        path = path[7:]

    # Se o arquivo não existir, devolve um resultado vazio com tipo None
    if not os.path.exists(path):
        return {prefix: {"type": None, "path": None}}

    # Determina o tipo a partir da extensão
    _, ext = os.path.splitext(path)
    ext = ext.lower()

    # mapeamento simples de extensões
    asset_exts = {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".svg", ".pdf", ".mp4", ".mp3", ".wav"}
    rendition_exts = {".xml", ".json", ".yaml", ".yml"}

    if ext in asset_exts:
        file_type = "asset"
    elif ext in rendition_exts:
        file_type = "rendition"
    else:
        # tenta decifrar pelo conteúdo se for possível
        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                sample = f.read(512).lower()
                if "<svg" in sample or (ext in asset_exts):
                    file_type = "asset"
                elif "<package" in sample or ("<rendition" in sample):
                    file_type = "rendition"
                else:
                    file_type = "unknown"
        except Exception:
            file_type = "unknown"

    return {prefix: {"type": file_type, "path": path}}
