def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
        A dictionary where keys are the base names (without extension) of XML files found in the zip,
        and values are dictionaries mapping each member's full path inside the zip to its byte contents.
    """
    import os
    import zipfile

    # Validate input
    if not isinstance(zip_path, str) or not zip_path:
        return {}

    if not os.path.isfile(zip_path):
        # Path does not exist or is not a file
        return {}

    package_data = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                # Skip directories
                if info.is_dir():
                    continue

                # Determine the base name (without extension) of the XML file
                filename = os.path.basename(info.filename)
                base, ext = os.path.splitext(filename)

                # Only consider files that have the same base name as some XML file
                # (i.e., skip files whose base name does not have a corresponding .xml counterpart)
                # To avoid requiring an explicit XML check, we'll group all files by basename regardless.
                # Note: If you want to restrict to XML packages specifically, you may add an extra
                # check here that ensures at least one XML file with that basename exists.

                if base not in package_data:
                    package_data[base] = {}
                try:
                    data = zf.read(info)
                except Exception:
                    # Skip file if reading fails
                    continue
                package_data[base][info.filename] = data
    except zipfile.BadZipFile:
        # Not a valid zip archive
        return {}
    except Exception:
        # Catch any other unexpected errors but do not crash
        return {}

    return package_data<|return|>

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        A dictionary mapping each XML base name to a list of tuples
        ``(filename, file_bytes)`` for all files belonging to that package.
    """
    import os
    from zipfile import ZipFile, BadZipFile

    grouped_data = {}
    try:
        with ZipFile(zip_path, 'r') as zf:
            # First pass: identify XML files and map them to their base names
            xml_to_base = {}
            for info in zf.infolist():
                if not info.is_dir() and info.filename.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(info.filename))[0]
                    xml_to_base[info.filename] = base
                    grouped_data.setdefault(base, []).append(
                        (info.filename, zf.read(info))
                    )

            # Second pass: associate non-XML files with the nearest XML file in the same directory
            for info in zf.infolist():
                if info.is_dir() or info.filename.lower().endswith('.xml'):
                    continue
                dirname = os.path.dirname(info.filename)
                # Find an XML file in the same directory
                related_xml = None
                for xml_path in xml_to_base:
                    if os.path.dirname(xml_path) == dirname:
                        related_xml = xml_path
                        break
                if related_xml:
                    base = xml_to_base[related_xml]
                    grouped_data.setdefault(base, []).append(
                        (info.filename, zf.read(info))
                    )
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Zip file not found: {zip_path}") from e
    except BadZipFile as e:
        raise BadZipFile(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        # Catch any other unexpected exception and re-raise with context
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

    return grouped_data<|return|>

