def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate the input arguments
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")
    if not isinstance(debug, bool):
        raise ValueError("debug must be a boolean")

    # Helper function to render an individual value
    def _render_value(val, current_indent):
        # If the value has its own pretty method, use it (guard against self recursion)
        try:
            pretty_method = getattr(val, "pretty", None)
            if callable(pretty_method) and val is not self:
                # Increase indent for nested pretty representation
                return pretty_method(current_indent + 2, debug=debug)
        except Exception:
            pass
        # Fallback to repr
        try:
            return repr(val)
        except Exception:
            return "<unrepresentable>"

    # Start building the pretty string
    indent_str = " " * indent
    lines = [f"{indent_str}{self.__class__.__name__}("]
    # Iterate over instance attributes (excluding private ones)
    for key in sorted(self.__dict__):
        if key.startswith("_"):
            continue
        try:
            value = getattr(self, key)
        except Exception:
            value = "<error retrieving>"
        value_str = _render_value(value, indent)
        lines.append(f"{indent_str}  {key}={value_str}")
    lines.append(f"{indent_str})")

    # Optional debug information
    if debug:
        lines.append(f"{indent_str}# type: {type(self).__name__}")

    return "\n".join(lines)<|return|>

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate parameters
    if not isinstance(indent, int) or indent < 0:
        raise TypeError('indent must be a non‑negative integer')
    if not isinstance(debug, bool):
        raise TypeError('debug must be a boolean')
    max_depth = 10
    visited = set()
    def _format(obj, level):
        if id(obj) in visited:
            return '<recursive>'
        if level > max_depth:
            return '...'
        visited.add(id(obj))
        if isinstance(obj, (int, float, bool, type(None))):
            return repr(obj)
        if isinstance(obj, str):
            return f'"{obj}"'
        if isinstance(obj, dict):
            items = []
            for k, v in sorted(obj.items(), key=lambda kv: str(k)):
                items.append(f'{_format(k, level+1)}: {_format(v, level+1)}')
            return '{' + ', '.join(items) + '}'
        if isinstance(obj, (list, tuple)):
            brackets = ('[', ']') if isinstance(obj, list) else ('(', ')')
            items = [_format(item, level+1) for item in obj]
            return brackets[0] + ', '.join(items) + brackets[1]
        if isinstance(obj, set):
            items = [_format(item, level+1) for item in obj]
            return '{' + ', '.join(items) + '}'
        # For user-defined objects
        if hasattr(obj, '__dict__'):
            cls_name = obj.__class__.__name__
            attrs = []
            for key, val in sorted(obj.__dict__.items()):
                attrs.append(f'{key}={_format(val, level+1)}')
            result = f'{cls_name}(' + ', '.join(attrs) + ')'
            if debug:
                result += f' [{cls_name}]'
            return result
        return repr(obj)
    return _format(self, indent)<|return|>

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    if not isinstance(indent, int):
        raise TypeError("indent must be an integer")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    def _fmt(value, level):
        pref = " " * level
        try:
            # Recurse into custom objects with their own pretty method
            pretty_attr = getattr(value, "pretty", None)
            if callable(pretty_attr):
                return value.pretty(level, debug)
            # Pretty format dictionaries
            if isinstance(value, dict):
                if not value:
                    return "{}"
                lines = [f"{pref}  {{"]  # opening brace
                for k in sorted(value):
                    lines.append(f"{pref}    {repr(k)}: {_fmt(value[k], level + 4)}")
                lines.append(f"{pref}  }}")  # closing brace
                return "\n".join(lines)
            # Pretty format sequences
            if isinstance(value, (list, tuple, set)):
                typ = type(value).__name__
                if not value:
                    return f"{typ}()"
                lines = [f"{pref}  {typ}("]
                for item in value:
                    lines.append(f"{pref}    {_fmt(item, level + 4)}")
                lines.append(f"{pref}  )")
                return "\n".join(lines)
        except Exception:
            return f"<{type(value).__name__}>"
        return repr(value)

    try:
        attrs = {}
        if hasattr(self, "__dict__"):
            attrs = dict(self.__dict__)
        elif hasattr(self, "__slots__"):
            for slot in getattr(self, "__slots__", []):
                attrs[slot] = getattr(self, slot)
        if debug:
            attrs["_debug_info"] = f"id={id(self)}, type={type(self).__name__}"
        if not attrs:
            return f"{self.__class__.__name__}()"

        lines = []
        for key in sorted(attrs):
            lines.append(f"{' ' * (indent + 4)}{repr(key)}: {_fmt(attrs[key], indent + 4)}")

        return (
            f"{self.__class__.__name__}(\n"
            + "\n".join(lines)
            + f"\n{' ' * indent})"
        )
    except Exception:
        return f"<Error generating pretty representation of {type(self).__name__}>"

<|return|>

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    visited = set()

    def _format(obj, depth):
        if id(obj) in visited:
            return ' ' * depth + '<recursion>'
        visited.add(id(obj))

        if hasattr(obj, "__dict__"):
            lines = []
            prefix = ' ' * depth
            if debug:
                lines.append(prefix + f"<{obj.__class__.__name__} id={id(obj):#x}>")
            for key, value in obj.__dict__.items():
                if isinstance(value, (list, tuple)):
                    sub_lines = []
                    for item in value:
                        sub_lines.append(_format(item, depth + 4))
                    lines.append(prefix + f"{key}:\n" + "\n".join(sub_lines))
                elif hasattr(value, "__dict__"):
                    lines.append(prefix + f"{key}:\n" + _format(value, depth + 4))
                else:
                    lines.append(prefix + f"{key}: {repr(value)}")
            visited.remove(id(obj))
            return "\n".join(lines)
        else:
            visited.remove(id(obj))
            return ' ' * depth + repr(obj)

    return _format(self, indent)<|return|>

def absorb(self, args):
    """
    Given an `args` sequence of sympy Boolean expressions, return a new list of
    expressions after applying absorption and negative absorption.

    Absorption::

        A & (A | B) == A
        A | (A & B) == A

    Negative absorption::

        A & (~A | B) == A & B
        A | (~A & B) == A | B

    Parameters
    ----------
    args : iterable
        Sequence of sympy expressions to simplify.

    Returns
    -------
    list
        List of simplified expressions.

    Raises
    ------
    ValueError
        If *args* is not an iterable.
    """
    try:
        iterator = iter(args)
    except TypeError:
        raise ValueError("`args` must be an iterable of expressions")
    from sympy import And, Or, Not, Basic

    def _absorb_expr(expr: Basic) -> Basic:
        """Apply absorption rules to a single expression."""
        # Keep applying rules until the expression is stable
        while True:
            prev = expr

            if isinstance(expr, And):
                terms = set(expr.args)
                # A & (A | B)  ->  A
                for sub in expr.args:
                    if isinstance(sub, Or):
                        if set(sub.args).intersection(terms):
                            # Find the common term
                            common = list(set(sub.args).intersection(terms))[0]
                            expr = common
                            break
                else:
                    # A & (~A | B) -> A & B
                    for sub in expr.args:
                        if isinstance(sub, Or):
                            for part in sub.args:
                                if isinstance(part, Not) and part.args[0] in terms:
                                    # Remove the ~A part
                                    new_terms = tuple(t for t in expr.args if t != part)
                                    expr = And(*new_terms)
                                    break
                            else:
                                continue
                            break

            elif isinstance(expr, Or):
                terms = set(expr.args)
                # A | (A & B) -> A
                for sub in expr.args:
                    if isinstance(sub, And):
                        if set(sub.args).intersection(terms):
                            common = list(set(sub.args).intersection(terms))[0]
                            expr = common
                            break
                else:
                    # A | (~A & B) -> A | B
                    for sub in expr.args:
                        if isinstance(sub, And):
                            for part in sub.args:
                                if isinstance(part, Not) and part.args[0] in terms:
                                    new_terms = tuple(t for t in expr.args if t != part)
                                    expr = Or(*new_terms)
                                    break
                            else:
                                continue
                            break

            if expr == prev:
                break
        return expr

    simplified = []
    for e in iterator:
        try:
            simplified.append(_absorb_expr(e))
        except Exception:
            # If an expression cannot be simplified, keep it unchanged
            simplified.append(e)
    return simplified<|return|>

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        # If sympy is available we use its expression structures.
        # We guard against missing types by using hasattr checks.
        from sympy import And, Or, Not
        is_and = lambda e: isinstance(e, And)
        is_or = lambda e: isinstance(e, Or)
        is_not = lambda e: isinstance(e, Not)
        res = []

        for expr in args:
            new_expr = expr

            # ------------------------------------------------------------------
            # Absorption patterns for And
            #   A & (A | B) -> A
            # ------------------------------------------------------------------
            if is_and(new_expr):
                # Look for a subexpression of the form (A | B) where one child
                # equals another child of the And.
                for a in new_expr.args:
                    if is_or(a):
                        for sub in a.args:
                            # check if the other child of the And equals sub
                            if sub in new_expr.args:
                                # Replace the whole expression with sub
                                new_expr = sub
                                break
                        if new_expr is not expr:
                            break

                # ------------------------------------------------------------------
                # Negative absorption for And
                #   A & (~A | B) -> A & B
                # ------------------------------------------------------------------
                if is_and(new_expr) and new_expr is expr:
                    # First term is A
                    if len(new_expr.args) == 2:
                        a, b = new_expr.args
                        # Check if one term is Or containing ~A and B
                        if is_or(a):
                            # need pattern (~A | B) where A is other term
                            other = new_expr.args[1]
                            # Build set of children of the Or
                            or_terms = set(a.args)
                            if is_not(other) and other.args[0] in or_terms:
                                # Here a is (~A | B)
                                # Replace with And(other, B)
                                or_terms.discard(is_not(other))
                                if len(or_terms) == 1:
                                    B_val = next(iter(or_terms))
                                else:
                                    B_val = Or(*or_terms)
                                new_expr = And(other, B_val)
                        elif is_or(b):
                            other = new_expr.args[0]
                            or_terms = set(b.args)
                            if is_not(other) and other.args[0] in or_terms:
                                or_terms.discard(is_not(other))
                                if len(or_terms) == 1:
                                    B_val = next(iter(or_terms))
                                else:
                                    B_val = Or(*or_terms)
                                new_expr = And(other, B_val)

            # ------------------------------------------------------------------
            # Absorption patterns for Or
            #   A | (A & B) -> A
            # ------------------------------------------------------------------
            if is_or(new_expr):
                for a in new_expr.args:
                    if is_and(a):
                        for sub in a.args:
                            if sub in new_expr.args:
                                new_expr = sub
                                break
                        if new_expr is not expr:
                            break

                # ------------------------------------------------------------------
                # Negative absorption for Or
                #   A | (~A & B) -> A | B
                # ------------------------------------------------------------------
                if is_or(new_expr) and new_expr is expr:
                    if len(new_expr.args) == 2:
                        a, b = new_expr.args
                        if is_and(a):
                            other = new_expr.args[1]
                            # pattern (~A & B) where A is other
                            if is_not(other) and other.args[0] in a.args:
                                and_terms = set(a.args)
                                and_terms.discard(is_not(other))
                                if len(and_terms) == 1:
                                    B_val = next(iter(and_terms))
                                else:
                                    B_val = And(*and_terms)
                                new_expr = Or(other, B_val)
                        elif is_and(b):
                            other = new_expr.args[0]
                            if is_not(other) and other.args[0] in b.args:
                                and_terms = set(b.args)
                                and_terms.discard(is_not(other))
                                if len(and_terms) == 1:
                                    B_val = next(iter(and_terms))
                                else:
                                    B_val = And(*and_terms)
                                new_expr = Or(other, B_val)

            res.append(new_expr)

        return res

    except Exception as exc:
        # Preserve original context for debugging
        raise RuntimeError(f"Failed to apply absorption rules: {exc}") from exc<|return|>

def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.
        """
        if hook is None:
            raise ValueError("Hook value cannot be None")

        # Ensure the registry exists
        if not hasattr(self, "_registry"):
            self._registry = {}

        # Prepare the list for the hook if not already present
        if hook not in self._registry:
            self._registry[hook] = []

        def decorator(func):
            if not callable(func):
                raise TypeError(f"Expected a callable listener, got {type(func).__name__}")
            try:
                self._registry[hook].append(func)
            except Exception as exc:
                # In case of any unexpected error, raise a descriptive exception
                raise RuntimeError(f"Failed to register handler {func!r} for hook {hook!r}") from exc
            return func

        return decorator<|return|>

