        hook.
    """
    if hook is None:
        raise TypeError("Hook value cannot be None")
    # Ensure the registry dictionary exists
    if not hasattr(self, "_registry"):
        self._registry = {}
    # Lazily initialize the list/set of handlers for this hook
    if hook not in self._registry:
        # Use a list to preserve registration order
        self._registry[hook] = []
    def decorator(func):
        if not callable(func):
            raise TypeError("Registered handler must be callable")
        # Avoid duplicate registrations
        if func not in self._registry[hook]:
            self._registry[hook].append(func)
        return func
    return decorator<|return|>

def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.
        """
        if hook is None:
            raise ValueError("Hook cannot be None")

        def decorator(fn):
            try:
                if not callable(fn):
                    raise TypeError(
                        f"Listener must be callable, got {type(fn).__name__}"
                    )
                # Retrieve or create the registry dictionary.
                registry = getattr(self, "_registry", None)
                if registry is None:
                    registry = {}
                    setattr(self, "_registry", registry)

                # Retrieve or create the listener list for this hook.
                listeners = registry.get(hook, [])
                if fn not in listeners:
                    listeners.append(fn)
                    registry[hook] = listeners
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to register handler for hook '{hook}'"
                ) from exc

            return fn

        return decorator<|return|>

