def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings.
    """
    import sys

    try:
        name = namefunc()
    except Exception as exc:
        # Propagate the exception with a more descriptive message
        raise RuntimeError(f"Error calling tzname function: {exc}") from exc

    # If the function returned something that is not a string, return it as-is
    if not isinstance(name, (str, bytes)):
        return name

    # In Python 3, unicode strings are returned – return them unchanged
    if sys.version_info[0] >= 3:
        return name

    # In Python 2, distinguish between bytes and unicode
    # 'unicode' type exists only in Python 2
    try:
        unicode_type = unicode  # noqa: F821
    except NameError:
        # We are not in Python 2 – just return the name
        return name

    if isinstance(name, unicode_type):
        # Convert unicode to a bytestring using UTF-8 encoding
        try:
            return name.encode('utf-8')
        except Exception as exc:
            # Fall back to ASCII encoding, ignoring errors
            return name.encode('ascii', 'ignore')
    else:
        # Already a bytestring; return as-is
        return name
<|return|>

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings. This helper returns a function that will call ``namefunc``
    and, if necessary, convert its result to a bytestring for Python 2.
    If ``namefunc`` is not callable, a ``TypeError`` is raised.
    Any exception raised by ``namefunc`` is propagated unchanged.
    """
    import sys

    if not callable(namefunc):
        raise TypeError("namefunc must be callable")

    def _wrapper(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception as exc:
            # Propagate any exception from the wrapped function
            raise exc

        # If the result is None, just return it
        if result is None:
            return None

        # Detect python version
        py2 = sys.version_info[0] == 2

        try:
            if py2:
                # In Python 2, ``unicode`` is a real type
                if isinstance(result, unicode):  # type exists only in py2
                    return result.encode('utf-8', errors='replace')
            else:
                # In Python 3, ``str`` is Unicode
                if isinstance(result, str):
                    return result.encode('utf-8', errors='replace')
        except Exception:
            # If encoding fails, fall back to the original result
            return result

        # Return the original result if no conversion is needed
        return result

    return _wrapper<|return|>

def get_versions():
    """
    Get version information or return default if unable to do so.

    Returns:
        str: The distribution version containing this module, or ``"0.0.0"`` if the
        version cannot be determined.
    """
    # Helper: try importlib.metadata (available from Python 3.8+)
    dist_name = __package__ or __name__  # Fallback if no package defined
    try:
        from importlib.metadata import version, PackageNotFoundError

        try:
            return version(dist_name)
        except PackageNotFoundError:
            pass  # Fall through to next method
        except Exception:
            # Any other issue (e.g., missing metadata files)
            pass
    except ImportError:
        # importlib.metadata not available, fall through
        pass

    # Fallback: pkg_resources (from setuptools)
    try:
        import pkg_resources

        try:
            return pkg_resources.get_distribution(dist_name).version
        except Exception:
            pass
    except Exception:
        pass

    # Final default if all else fails
    return "0.0.0"<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    import subprocess
    import re
    # Try to get a version string from git
    try:
        output = subprocess.check_output(
            ['git', 'describe', '--tags', '--dirty', '--always'],
            stderr=subprocess.STDOUT,
            text=True,
        ).strip()
        # Extract a numeric version (e.g., 1.2.3) if present
        match = re.search(r'([0-9]+\.[0-9]+(?:\.[0-9]+)?)', output)
        if match:
            return match.group(1)
        # Fallback to the raw git describe string if no numeric part
        return output
    except Exception:
        # If git is unavailable or any other error, ignore and continue
        pass

    # Try to get the version from package metadata
    try:
        import importlib.metadata as _metadata
        # Attempt to determine the package name from the module's package
        pkg_name = __package__
        if not pkg_name:
            # If __package__ is empty (e.g., running as script), try to deduce from module name
            pkg_name = __name__.split('.')[0]
        if pkg_name:
            return _metadata.version(pkg_name)
    except Exception:
        # Ignore failures from importlib.metadata
        pass

    # Default fallback if all other methods fail
    return "0.0.0"<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Determine the package name from the module's top-level package
        pkg_name = __name__.split('.')[0]
        from importlib.metadata import version, PackageNotFoundError
        full_version = version(pkg_name)
        short_version = ".".join(full_version.split(".")[:2])
