        # Fallback default if any step fails
        return {"full": "0.0.0", "short": "0.0"}<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    # Use importlib.metadata if available (Python 3.8+)
    try:
        from importlib.metadata import version, PackageNotFoundError
        get_version = lambda name: version(name)
        pkg_not_found = PackageNotFoundError
    except ImportError:
        # Fallback to pkg_resources (setuptools) if importlib.metadata is not available
        try:
            import pkg_resources

            def get_version(name):
                return pkg_resources.get_distribution(name).version

            pkg_not_found = Exception
        except Exception:
            # If both modules cannot be imported, return default version information
            return {"full": "0.0.0", "short": "0.0.0"}

    # Determine the package name from the current module/context
    package_name = __package__ or __name__
    if not package_name:
        # Package name could not be resolved, return default
        return {"full": "0.0.0", "short": "0.0.0"}

    try:
        full_version = get_version(package_name)
    except pkg_not_found:
        # The package is not installed or distribution metadata not available
        return {"full": "0.0.0", "short": "0.0.0"}
    except Exception:
        # Any other error while retrieving version
        return {"full": "0.0.0", "short": "0.0.0"}

    # Compute a short version string (major.minor if available)
    try:
        parts = full_version.split(".")
        short_version = ".".join(parts[:2]) if len(parts) >= 2 else full_version
    except Exception:
        short_version = full_version

    return {"full": full_version, "short": short_version}<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Try to get the version of the current package using importlib.metadata
        from importlib.metadata import distribution, PackageNotFoundError
        # Use the top-level package name from the module's __name__
        pkg_name = __name__.split('.')[0]
        # Avoid mismatch when running as a script
        if pkg_name == "__main__":
            raise PackageNotFoundError
        dist = distribution(pkg_name)
        return {pkg_name: dist.version}
    except Exception:
        # Fallback to a sensible default when version info cannot be obtained
        return {"default_version": "0.0.0"}<|return|>

