def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if not commands:
        raise ValueError("No command specified")
    if isinstance(commands, str):
        try:
            cmd_list = shlex.split(commands)
        except Exception as exc:
            raise ValueError(f"Failed to parse command string: {commands}") from exc
    else:
        cmd_list = list(commands)

    if args:
        if isinstance(args, str):
            try:
                args_list = shlex.split(args)
            except Exception as exc:
                raise ValueError(f"Failed to parse args string: {args}") from exc
        else:
            args_list = list(args)
        cmd_list.extend(args_list)

    if verbose:
        print(f"Executing: {' '.join(cmd_list)}")

    # Configure stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=stderr,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {cmd_list[0]}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run command: {' '.join(cmd_list)}") from exc

    if result.returncode != 0:
        err_msg = result.stderr.strip() if not hide_stderr and result.stderr else ""
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=cmd_list,
            output=result.stdout,
            stderr=err_msg,
        )

    return result.stdout.strip()
