def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Helper to recursively gather objects from a nested structure
    def _gather(node):
        """
        Yield leaf objects from a potentially nested hierarchy.
        A node is considered a leaf if it is not a dict/list or if it has no 'children' key.
        """
        if isinstance(node, dict):
            # If the node has a 'children' key, recurse into each child
            children = node.get("children")
            if children and isinstance(children, list):
                for child in children:
                    yield from _gather(child)
                return
        # Otherwise treat node itself as an object
        yield node

    try:
        # Determine the root of the hierarchy
        root = getattr(self, "storage_root", None)
        if root is None:
            # Fall back to an attribute that might hold the hierarchy
            root = getattr(self, "root", None)
        if root is None:
            if show_warnings:
                print("validate_hierarchy: No storage_root or root attribute found")
            return num_objects, good_objects

        # Flatten the hierarchy into a list of objects
        objects = list(_gather(root))

        for obj in objects:
            num_objects += 1
            is_valid = True

            # Validate the object itself, if requested and if a method exists
            if validate_objects:
                try:
                    # Assume a method validate_object that returns True/False
                    is_valid = getattr(self, "validate_object", lambda o: True)(obj)
                except Exception as exc:
                    if show_warnings:
                        print(f"validate_hierarchy: Exception in validate_object({obj}): {exc}")
                    is_valid = False

            # Additional digest check, if requested
            if check_digests and is_valid:
                try:
                    # Example: objects may be dicts with 'expected_digest' and 'actual_digest' keys
                    expected = obj.get("expected_digest") if isinstance(obj, dict) else None
                    actual = obj.get("actual_digest") if isinstance(obj, dict) else None
                    if expected is not None and actual is not None:
                        is_valid = expected == actual
                except Exception as exc:
                    if show_warnings:
                        print(f"validate_hierarchy: Digest check failed for {obj}: {exc}")
                    is_valid = False

            if is_valid:
                good_objects += 1
            else:
                if show_warnings:
                    print(f"validate_hierarchy: Validation failed for object: {obj}")

    except Exception as exc:
        if show_warnings:
            print(f"validate_hierarchy: Unexpected error: {exc}")
        # Depending on policy, we could re-raise or swallow; here we swallow to return counts.

    return num_objects, good_objects
<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    import hashlib
    import warnings
    from pathlib import Path

    num_objects = 0
    good_objects = 0

    # Determine which objects to validate
    try:
        if hasattr(self, "objects") and isinstance(self.objects, (dict, list)):
            # If self.objects is a dict or list, iterate over its items/values
            objects_iter = self.objects.values() if isinstance(self.objects, dict) else self.objects
        elif hasattr(self, "root"):
            # Assume self.root is a filesystem path (string or Path)
            root_path = Path(self.root)
            if not root_path.exists():
                raise FileNotFoundError(f"Root path {self.root} does not exist")
            objects_iter = root_path.rglob("*")
        else:
            # Nothing to do if we cannot locate the hierarchy
            raise AttributeError("No recognizable storage hierarchy found")
    except Exception as exc:
        if show_warnings:
            warnings.warn(f"Failed to locate data hierarchy: {exc}")
        return num_objects, good_objects

    for obj in objects_iter:
        if isinstance(obj, Path):
            obj_path = obj
        else:
            try:
                obj_path = Path(str(obj))
            except Exception:
                # Skip items that cannot be converted to Path
                if show_warnings:
                    warnings.warn(f"Skipping non-path object: {obj}")
                continue

        if obj_path.is_file() or obj_path.is_dir():
            num_objects += 1
            is_valid = True

            # Basic validation: try to open files
            if validate_objects and obj_path.is_file():
                try:
                    with obj_path.open("rb") as f:
                        _ = f.read(1)
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        warnings.warn(f"File {obj_path} failed basic validation: {exc}")

            # Digest validation (optional)
            if is_valid and check_digests and obj_path.is_file():
                try:
                    # Expect a .digest file in the same directory named <filename>.digest
                    digest_file = obj_path.with_suffix(obj_path.suffix + ".digest")
                    if digest_file.exists():
                        expected = digest_file.read_text().strip()
                        actual = hashlib.sha256(obj_path.read_bytes()).hexdigest()
                        if actual != expected:
                            is_valid = False
                            if show_warnings:
                                warnings.warn(f"Digest mismatch for {obj_path}")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        warnings.warn(f"Digest check failed for {obj_path}: {exc}")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects<|return|>

