def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if isinstance(version, int):
            if version < 0:
                raise ValueError("negative integer not allowed")
            return str(version + 1)

        if not isinstance(version, str):
            raise TypeError("version must be a str or int")

        if not version:
            raise ValueError("empty string")

        # Determine if the string contains only digits
        if not version.isdigit():
            raise ValueError("non‑digit characters present")

        # Convert to integer and increment
        num = int(version) + 1
        result = str(num)

        # Preserve zero padding if original had leading zeros
        if version.startswith('0'):
            width = len(version)
            result = result.rjust(width, '0')

        return result

    except Exception as exc:
        raise ValueError(f"invalid version '{version}': {exc}") from exc<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise ValueError("version must be a string")
    if version == "":
        raise ValueError("version string cannot be empty")

    parts = version.split('.')
    if not parts:
        raise ValueError("invalid version format")

    try:
        # Process the last component
        last = parts[-1]
        # Ensure the last component is numeric
        if not last.isdigit():
            raise ValueError(f"Non-numeric component in version: {last}")

        original_len = len(last)
        new_value = int(last) + 1
        new_last = str(new_value).zfill(original_len)

        # Reconstruct the version string
        new_parts = parts[:-1] + [new_last]
        return ".".join(new_parts)
    except Exception as e:
        raise ValueError(f"Failed to compute next version for '{version}': {e}") from e<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    v = version.strip()
    if not v:
        raise ValueError("empty version string")
    if not v.isdigit():
        raise ValueError("version must contain only digits")
    # Detect zero prefix (excluding the single-digit zero case)
    zero_prefixed = len(v) > 1 and v[0] == '0'
    new_num = int(v) + 1
    if zero_prefixed:
        # Preserve original width
        return str(new_num).zfill(len(v))
    else:
        return str(new_num)<|return|>

def validate_version_inventories(self, version_dirs):
    """
    Validate that each specified version directory contains an inventory file
    that matches the root inventory up to that point, and record any digest
    differences for later validation.

    Returns:
        dict: A mapping of file paths to a tuple of
              (root_digest, version_digest) for entries whose digests differ.
              If all inventories match the root, an empty dict is returned.

    Raises:
        FileNotFoundError: If a required inventory file is missing.
        ValueError: If an inventory file contains malformed data.
    """
    import os, json

    def _parse_inventory(content):
        """Parse inventory content into a dict of {path: digest}."""
        content = content.strip()
        if not content:
            return {}
        # Try JSON first
        try:
            return {str(k): str(v) for k, v in json.loads(content).items()}
        except Exception:
            pass
        # Fallback to simple "digest path" lines
        result = {}
        for line in content.splitlines():
            line = line.strip()
            if not line:
                continue
            parts = line.split(None, 1)
            if len(parts) != 2:
                continue  # skip malformed lines
            digest, path = parts
            result[path] = digest
        return result

    # Load the root inventory
    root_inventory_path = os.path.join(self.root_dir, "inventory")
    try:
        with open(root_inventory_path, "r", encoding="utf-8") as f:
            root_content = f.read()
    except FileNotFoundError:
        raise FileNotFoundError(f"Root inventory not found at {root_inventory_path}")
    except Exception as exc:
        raise ValueError(f"Error reading root inventory at {root_inventory_path}: {exc}")

    root_digests = _parse_inventory(root_content)

    differences = {}

    for ver_dir in version_dirs:
        ver_inventory_path = os.path.join(self.root_dir, ver_dir, "inventory")
        try:
            with open(ver_inventory_path, "r", encoding="utf-8") as f:
                ver_content = f.read()
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory for version '{ver_dir}' not found at {ver_inventory_path}")
        except Exception as exc:
            raise ValueError(f"Error reading inventory at {ver_inventory_path}: {exc}")

        ver_digests = _parse_inventory(ver_content)

        # Ensure every entry in the version inventory matches or exists in the root
        for path, ver_digest in ver_digests.items():
            root_digest = root_digests.get(path)
            if root_digest != ver_digest:
                # Record difference; use None if missing in root
                differences.setdefault(path, []).append((ver_dir, root_digest, ver_digest))

        # Also check for paths present in root but missing in this version inventory
        for path, root_digest in root_digests.items():
            if path not in ver_digests:
                differences.setdefault(path, []).append((ver_dir, root_digest, None))

    # Flatten the differences into a single mapping of path -> (root, version) for last occurrence
    # If multiple versions differ, keep the latest difference encountered.
    final_diffs = {}
    for path, records in differences.items():
        # Pick the last record for simplicity
        _, root_digest, ver_digest = records[-1]
        final_diffs[path] = (root_digest, ver_digest)

    return final_diffs
