def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Validate input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not all(isinstance(v, str) for v in version_dirs):
        raise ValueError("All items in version_dirs must be strings representing folder names")

    # Ensure we have a root inventory loaded
    try:
        root_inventory = getattr(self, "root_inventory")
    except AttributeError:
        # Try to load from a default inventory file in the repository root
        try:
            import json, os
            root_path = os.path.join(self.base_path, "inventory.json")
            if not os.path.isfile(root_path):
                root_path = os.path.join(self.base_path, "inventory.yaml")
            with open(root_path, "r", encoding="utf-8") as f:
                if root_path.endswith(".yaml") or root_path.endswith(".yml"):
                    # fall back to yaml if available; do a basic import
                    try:
                        import yaml
                        root_inventory = yaml.safe_load(f)
                    except Exception:
                        raise RuntimeError(f"Unable to load YAML root inventory at {root_path}")
                else:
                    root_inventory = json.load(f)
            if not isinstance(root_inventory, dict):
                raise ValueError(f"Root inventory file {root_path} does not contain a mapping")
            self.root_inventory = root_inventory
        except Exception as exc:
            raise RuntimeError("Failed to load the root inventory") from exc
    else:
        if not isinstance(root_inventory, dict):
            raise ValueError("root_inventory attribute is not a dictionary")

    # This dict will keep differences for each content item across all revisions
    content_differences = {}

    for ver_dir in version_dirs:
        inv_path = os.path.join(ver_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            # Try alternate format
            inv_path_alt = os.path.join(ver_dir, "inventory.yaml")
            if os.path.isfile(inv_path_alt):
                inv_path = inv_path_alt
            else:
                raise FileNotFoundError(f"No inventory file found in version directory: {ver_dir}")

        try:
            import json
            with open(inv_path, "r", encoding="utf-8") as f:
                if inv_path.endswith((".yaml", ".yml")):
                    try:
                        import yaml
                        version_inventory = yaml.safe_load(f)
                    except Exception as exc:
                        raise RuntimeError(f"Failed to parse YAML inventory at {inv_path}") from exc
                else:
                    version_inventory = json.load(f)
        except Exception as exc:
            raise RuntimeError(f"Unable to load inventory from {inv_path}") from exc

        if not isinstance(version_inventory, dict):
            raise ValueError(f"Inventory file {inv_path} does not contain a mapping")

        # Verify that the current inventory contains all items from the root.
        missing_items = [k for k in root_inventory if k not in version_inventory]
        if missing_items:
            raise ValueError(f"Inventory in {ver_dir} is missing items: {missing_items}")

        # Compare digests and record differences
        for key, root_digest in root_inventory.items():
            ver_digest = version_inventory.get(key)
            if ver_digest != root_digest:
                content_differences.setdefault(key, []).append((root_digest, ver_digest))

    # Attach the differences dictionary to the instance for later use
    self.content_differences = content_differences
    return content_differences
