def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Ensure required attributes exist
        if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
            raise ValueError("Root inventory is not set or is not a dictionary.")
        # Initialize or clear the record of differing digests
        self.differing_digests = {}
        # Helper: record a difference
        def _record_difference(item_id, version_dir, actual_digest, expected_digest):
            self.differing_digests.setdefault(item_id, []).append(
                {"version": version_dir, "actual": actual_digest, "expected": expected_digest}
            )
        # Iterate through each version directory in sequence
        for vdir in version_dirs:
            # Build path to the inventory file (assuming a standard name)
            inv_path = os.path.join(vdir, "inventory.json")
            try:
                with open(inv_path, "r", encoding="utf-8") as f:
                    inv_data = json.load(f)
            except FileNotFoundError:
                raise ValueError(f"Inventory file not found in version directory '{vdir}'. Expected at '{inv_path}'.")
            except json.JSONDecodeError as e:
                raise ValueError(f"Inventory file in '{vdir}' is not valid JSON: {e}")

            if not isinstance(inv_data, dict):
                raise ValueError(f"Inventory file in '{vdir}' does not contain a JSON object as expected.")

            # Validate that all expected items are present up to this version
            for item_id, expected_digest in self.root_inventory.items():
                if item_id not in inv_data:
                    raise ValueError(f"Missing item '{item_id}' in inventory of version '{vdir}'.")
                actual_digest = inv_data[item_id]
                if actual_digest != expected_digest:
                    _record_difference(item_id, vdir, actual_digest, expected_digest)

            # Optionally, warn if there are unexpected items in this inventory
            # (this part is optional and can be removed if not needed)
            unexpected = set(inv_data.keys()) - set(self.root_inventory.keys())
            if unexpected:
                # We simply record them under a special key '_unexpected'
                self.differing_digests.setdefault("_unexpected", []).append(
                    {"version": vdir, "items": list(unexpected)}
                )
        # Return the dictionary of differences for convenience
        return self.differing_digests
