def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Ensure the input is a string
    if not isinstance(path, str):
        return "Invalid path: must be a string"

    try:
        import os
        import re
    except Exception as e:
        return f"Import error: {e}"

    # Check existence
    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"
    except Exception as e:
        return f"Error checking existence: {e}"

    # If it's a file, return 'file'
    try:
        if os.path.isfile(path):
            return "file"
    except Exception as e:
        return f"Error determining file status: {e}"

    # If it's a directory
    try:
        if os.path.isdir(path):
            entries = os.listdir(path)
            # Look for '0=*' files
            for entry in entries:
                if re.match(r"^0=.*$", entry):
                    # Found a Namaste file; assume this is an OCFL object
                    return "object"
            # No Namaste file found
            # If directory contains subdirectories, treat as root
            for entry in entries:
                full_entry = os.path.join(path, entry)
                if os.path.isdir(full_entry):
                    return "root"
            # If directory is empty or only contains files but no Namaste marker
            return "unknown directory type"
    except PermissionError as pe:
        return f"Permission error accessing directory: {pe}"
    except OSError as oe:
        return f"OS error accessing directory: {oe}"
    except Exception as e:
        return f"Unexpected error: {e}"

    return "unable to determine type"<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return f"not exists: {path}"
        if os.path.isfile(path) or os.path.islink(path):
            return "file"
        if not os.path.isdir(path):
            return f"unknown type: {path}"
        # Directory case
        try:
            entries = os.listdir(path)
        except OSError as e:
            return f"cannot list directory '{path}': {e}"
        # Check if the directory itself contains a Namaste file
        namaste_files = [e for e in entries if e.startswith("0=") and os.path.isfile(os.path.join(path, e))]
        if namaste_files:
            return "object"
        # If not object, check if any immediate subdirectory contains Namaste files
        for entry in entries:
            sub_path = os.path.join(path, entry)
            if os.path.isdir(sub_path):
                try:
                    sub_entries = os.listdir(sub_path)
                except OSError:
                    continue
                sub_namaste = [e for e in sub_entries if e.startswith("0=") and os.path.isfile(os.path.join(sub_path, e))]
                if sub_namaste:
                    return "root"
        # If no Namaste files found
        return f"not an OCFL root or object: {path}"
    except Exception as exc:
        return f"error analyzing path '{path}': {exc}"
