def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        import glob
    except Exception as exc:
        return f"import error: {exc}"

    if not path:
        return "empty_path"

    try:
        if not os.path.exists(path):
            return f"path_not_found:{path}"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            # Check for Namaste object file
            if glob.glob(os.path.join(path, "0=*")):
                return "object"

            # Common markers that indicate a storage root
            root_markers = {".ocfl", ".ocfl-version", "ocfl_version.json", "ocfl.json"}
            for marker in root_markers:
                if os.path.isfile(os.path.join(path, marker)):
                    return "root"

            # Fallback heuristic: if any immediate subdirectory contains a Namaste file,
            # treat the original directory as a storage root.
            try:
                for entry in os.listdir(path):
                    sub = os.path.join(path, entry)
                    if os.path.isdir(sub) and glob.glob(os.path.join(sub, "0=*")):
                        return "root"
            except Exception:
                pass

            return "unknown"

        return f"unknown_path_type:{type(path)}"

    except Exception as exc:
        return f"error:{exc}"
