def deep_merge_nodes(nodes):
    """
    Merge a list of ruamel.yaml nodes with potentially duplicate keys.
    Duplicate keys with mapping values are deep merged, otherwise the last
    value wins.  The original key node objects are preserved.
    """
    # Helper: determine if a node is a MappingNode
    def is_mapping(node):
        try:
            return getattr(node, "tag", "") == "tag:yaml.org,2002:map"
        except Exception:
            return False

    # Deep merge two mapping nodes – returns a new MappingNode
    def merge_mapping_nodes(target, source):
        # copy target value list to avoid modifying original
        merged_entries = list(target.value)  # list of (key, value) tuples
        for src_key, src_val in source.value:
            # find if same key exists in merged_entries
            for idx, (tgt_key, tgt_val) in enumerate(merged_entries):
                if getattr(tgt_key, "value", None) == getattr(src_key, "value", None):
                    # duplicate key
                    if is_mapping(tgt_val) and is_mapping(src_val):
                        # recurse
                        merged_entries[idx] = (
                            tgt_key,
                            merge_mapping_nodes(tgt_val, src_val),
                        )
                    else:
                        # last wins
                        merged_entries[idx] = (tgt_key, src_val)
                    break
            else:
                # key not found, append
                merged_entries.append((src_key, src_val))
        # construct new MappingNode with same tag as target
        return type(target)(
            target.tag,
            merged_entries,
        )

    merged = {}
    key_nodes = {}
    for key_node, val_node in nodes:
        key = getattr(key_node, "value", None)
        if key is None:
            continue  # skip malformed
        if key in merged:
            existing = merged[key]
            if is_mapping(existing) and is_mapping(val_node):
                merged[key] = merge_mapping_nodes(existing, val_node)
            else:
                merged[key] = val_node
        else:
            merged[key] = val_node
            key_nodes[key] = key_node
    result = []
    for key, val_node in merged.items():
        result.append((key_nodes[key], val_node))
    return result
