def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    # If parser is None or does not have actions, return an empty string
    if parser is None:
        return ''
    try:
        actions = getattr(parser, "_actions", [])
    except Exception:
        return ''
    flags = []
    for action in actions:
        try:
            opt_strs = getattr(action, "option_strings", [])
            if opt_strs:
                # Filter out any empty strings and ensure they are str
                for opt in opt_strs:
                    if isinstance(opt, str) and opt:
                        flags.append(opt)
        except Exception:
            continue
    # Remove duplicates while preserving order
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)
    return ' '.join(unique_flags)<|return|>

