    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an integer, got {type(number).__name__}")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple of strings, got {type(alphabet).__name__}")
    if not alphabet:
        raise ValueError("alphabet must contain at least one character")

    base = len(alphabet)

    # Handle zero specially
    if number == 0:
        result = alphabet[0]
        negative = False
    else:
        negative = number < 0
        if negative:
            number = -number

        digits = []
        if base == 1:
            # Unary representation: repeat the symbol
            digits = [alphabet[0]] * number
        else:
            while number > 0:
                number, rem = divmod(number, base)
                digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    if negative:
        result = '-' + result

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an integer, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non‑negative")

        # Count digits excluding sign
        digit_len = len(result.lstrip('-'))
        if digit_len < padding:
            pad_needed = padding - digit_len
            pad_str = alphabet[0] * pad_needed
            if result.startswith('-'):
                result = '-' + pad_str + result[1:]
            else:
                result = pad_str + result

    return result
