    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number > 0:
            remainder = number % base
            digits.append(alphabet[remainder])
            number //= base
        digits.reverse()

    # Apply padding with the zero symbol
    if padding is not None:
        zero_symbol = alphabet[0]
        if len(digits) < padding:
            digits = [zero_symbol] * (padding - len(digits)) + digits

