        raise TypeError("register_number must be an integer")
    # Helper to recursively replace keys
    def _replace_in_obj(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for key, value in list(obj.items()):
                # Determine new key
                new_key = register_number if key == register_value else key
                # Recursively process value
                new_value = _replace_in_obj(value)
