    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise TypeError(f"Expected string, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"Expected list for alphabet, got {type(alphabet).__name__}")

    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    base = len(alphabet)
    if base < 2:
        raise ValueError(f"Alphabet must contain at least two symbols to form a valid base, got {base}")

    # Build a mapping from character to its numeric value
    index_map = {}
    for idx, symbol in enumerate(alphabet):
        if not isinstance(symbol, str) or len(symbol) != 1:
            raise ValueError(f"Alphabet elements must be single-character strings, got {symbol!r}")
        if symbol in index_map:
            raise ValueError(f"Duplicate symbol in alphabet: {symbol!r}")
