def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    try:
        from pathlib import Path
        from tempfile import NamedTemporaryFile
        import tarfile
        import requests
    except Exception as exc:
        raise RuntimeError(f"Required modules could not be imported: {exc}")

    # Ensure destination_path exists
    try:
        destination_path = Path(destination_path)
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise IOError(f"Could not create destination directory {destination_path!r}: {exc}")

    # Determine archive name from URL
    archive_name = Path(url).name
    # Remove trailing .tar.gz
    if archive_name.lower().endswith(".tar.gz"):
        archive_name = archive_name[:-7]
    elif archive_name.lower().endswith(".tar"):
        archive_name = archive_name[:-4]
    extraction_dir = destination_path / archive_name

    # If the directory already exists, assume extraction is done
    if extraction_dir.exists() and extraction_dir.is_dir():
        return extraction_dir.resolve()

    # Download the file to a temporary location
    try:
        with requests.get(url, stream=True, timeout=30) as resp:
            resp.raise_for_status()
            with NamedTemporaryFile(delete=False) as tmp_file:
                for chunk in resp.iter_content(chunk_size=8192):
                    if chunk:
                        tmp_file.write(chunk)
                tmp_path = Path(tmp_file.name)
    except requests.exceptions.RequestException as exc:
        raise IOError(f"Failed to download archive from {url!r}: {exc}") from exc

    # Extract the tarball
    try:
        with tarfile.open(tmp_path, mode="r|gz") as tar:
            tar.extractall(path=extraction_dir)
    except (tarfile.TarError, OSError) as exc:
        raise IOError(f"Failed to extract archive {tmp_path!r}: {exc}") from exc
    finally:
        # Clean up the temporary file
        try:
            tmp_path.unlink(missing_ok=True)
        except Exception:
            pass

    if not extraction_dir.exists() or not extraction_dir.is_dir():
        raise IOError(f"Extraction failed, directory not found: {extraction_dir!r}")

    return extraction_dir.resolve()
<|return|>

def get_repo_archive(url: str, destination_path: Path) -> Path:
    import os
    import tarfile
    import tempfile
    from pathlib import Path as _Path
    import requests

    # Validate arguments
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")
    if not isinstance(destination_path, _Path):
        raise ValueError("destination_path must be a pathlib.Path instance")

    # Ensure destination directory exists
    try:
        os.makedirs(destination_path, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Failed to create destination directory {destination_path!s}: {e}") from e

    # Download archive
    try:
        response = requests.get(url, stream=True, timeout=60)
        response.raise_for_status()
    except Exception as e:
        raise RuntimeError(f"Failed to download archive from {url!s}: {e}") from e

    # Write to temporary file
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp_file:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    tmp_file.write(chunk)
            tmp_path = Path(tmp_file.name)
    except Exception as e:
        raise RuntimeError(f"Failed to write temporary archive file: {e}") from e

    # Extract archive
    try:
        with tarfile.open(tmp_path, mode="r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as e:
        raise RuntimeError(f"Failed to extract archive to {destination_path!s}: {e}") from e
    finally:
        # Clean up temp file
        try:
            tmp_path.unlink(missing_ok=True)
        except Exception:
            pass  # Non-critical cleanup failure

    return destination_path<|return|>

