def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess

    # Ensure the archive exists
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    # Resolve tmp_path to string and ensure it exists
    tmp_path = str(tmp_path)
    if not os.path.isdir(tmp_path):
        try:
            os.makedirs(tmp_path, exist_ok=True)
        except Exception as e:
            raise RuntimeError(f"Unable to create temporary directory '{tmp_path}': {e}")

    # Determine the extraction directory name
    if filename:
        target_name = os.path.basename(filename)
        if not target_name:
            raise ValueError("Provided filename is empty")
    else:
        # Strip common archive extensions
        base = os.path.basename(archive_path)
        name = base
        while True:
            name, ext = os.path.splitext(name)
            if ext and ext.lower() not in {".z", ".gz", ".bz2", ".xz"}:
                break
        target_name = name if name else "extracted_repo"

    target_dir = os.path.join(tmp_path, target_name)

    # Ensure the target directory does not already exist
    if os.path.isdir(target_dir):
        raise FileExistsError(f"Target extraction directory already exists: {target_dir}")

    try:
        os.makedirs(target_dir, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Failed to create extraction directory '{target_dir}': {e}")

    # Identify archive type and run appropriate extraction command
    lower = archive_path.lower()
    if lower.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path, "-d", target_dir]
    elif lower.endswith((".tar.gz", ".tgz", ".tar.bz2", ".tar.xz", ".tar")):
        cmd = ["tar", "-xzf", archive_path, "-C", target_dir]
        if lower.endswith(".tar"):
            cmd[0] = "tar"  # still -xf is correct, but -zf is okay if gz
            cmd[1] = "-xf"
    else:
        raise ValueError(f"Unsupported archive format for file: {archive_path}")

    # Execute the extraction
    result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if result.returncode != 0:
        # Cleanup on failure
        try:
            import shutil
            shutil.rmtree(target_dir)
        except Exception:
            pass
        raise RuntimeError(
            f"Extraction failed for '{archive_path}'. "
            f"Command: {' '.join(cmd)}. "
            f"Stdout: {result.stdout}. Stderr: {result.stderr}"
        )

    # Return the file URL to the extracted repository
    return f"file://{os.path.abspath(target_dir)}"<|return|>

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import pathlib
    import subprocess
    import uuid

    # Validate archive_path
    archive = pathlib.Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    # Prepare extraction directory
    tmp = pathlib.Path(tmp_path).expanduser().resolve()
    if not tmp.is_dir():
        try:
            tmp.mkdir(parents=True, exist_ok=True)
        except Exception as e:
            raise RuntimeError(f"Could not create temporary directory {tmp}: {e}")

    # Use a unique subdirectory for extraction to avoid collisions
    extract_root = tmp / f"extract_{uuid.uuid4().hex}"
    try:
        extract_root.mkdir()
    except Exception as e:
        raise RuntimeError(f"Could not create extraction directory {extract_root}: {e}")

    # Determine extraction command based on file extension
    suffixes = archive.suffixes
    try:
        if suffixes[-2:] == [".tar", ".gz"] or archive.suffix == ".tgz":
            cmd = ["tar", "-xzf", str(archive), "-C", str(extract_root)]
        elif suffixes[-2:] == [".tar", ".bz2"]:
            cmd = ["tar", "-xjf", str(archive), "-C", str(extract_root)]
        elif suffixes[-2:] == [".tar", ".xz"]:
            cmd = ["tar", "-xJf", str(archive), "-C", str(extract_root)]
        elif suffixes[-1] == ".zip":
            cmd = ["unzip", "-q", str(archive), "-d", str(extract_root)]
        else:
            # Fallback: attempt to gunzip if possible
            if suffixes[-1] == ".gz":
                cmd = ["gunzip", "-c", str(archive)]
            else:
                raise ValueError(f"Unsupported archive format: {archive_path}")
        result = subprocess.run(cmd, capture_output=True, text=True)
        if result.returncode != 0:
            raise RuntimeError(f"Extraction failed: {result.stderr.strip()}")
    except Exception as exc:
        # Clean up extraction directory on failure
        try:
            pathlib.rmtree(extract_root)
        except Exception:
            pass
        raise RuntimeError(f"Failed to extract archive {archive_path}: {exc}")

    # Identify the root directory of the extracted content
    # If the archive contains a single top-level directory, use it; otherwise, use extract_root
    extracted_entries = list(extract_root.iterdir())
    repo_path = extract_root
    if len(extracted_entries) == 1 and extracted_entries[0].is_dir():
        repo_path = extracted_entries[0]

    # Ensure the path is absolute
    repo_path = repo_path.expanduser().resolve()

    # Create a repo URL. If the directory contains a .git folder, we assume it's a repo.
    # Otherwise, just return the path; downstream logic can initialize a repo if needed.
    return f"file://{repo_path}"<|return|>

