def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or "always" cases
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == 'always':
        return None

    # Frequency must be a string after this point
    if not isinstance(frequency, str):
        raise ValueError(f'Frequency must be a string or None, got {type(frequency)}')

    freq = frequency.strip()
    if not freq:
        raise ValueError('Frequency string cannot be empty')

    # Parse number and unit (e.g., "3 weeks")
    import re
    match = re.match(r'^(-?\d+)\s*([a-zA-Z]+)$', freq)
    if not match:
        raise ValueError(f'Cannot parse frequency: {frequency}')

    try:
        quantity = int(match.group(1))
    except ValueError:
        raise ValueError(f'Invalid numeric value in frequency: {match.group(1)}')

    unit_str = match.group(2).lower()
    unit_map = {
        # Seconds
        's': 'seconds', 'sec': 'seconds', 'secs': 'seconds', 'second': 'seconds', 'seconds': 'seconds',
        # Minutes
        'm': 'minutes', 'min': 'minutes', 'mins': 'minutes', 'minute': 'minutes', 'minutes': 'minutes',
        # Hours
        'h': 'hours', 'hr': 'hours', 'hrs': 'hours', 'hour': 'hours', 'hours': 'hours',
        # Days
        'd': 'days', 'day': 'days', 'days': 'days',
        # Weeks
        'w': 'weeks', 'week': 'weeks', 'weeks': 'weeks',
    }
    if unit_str not in unit_map:
        raise ValueError(f'Unknown time unit in frequency: {unit_str}')

    kwargs = {unit_map[unit_str]: quantity}
    try:
        return datetime.timedelta(**kwargs)
    except Exception as e:
        raise ValueError(f'Error creating timedelta from frequency "{frequency}": {e}')<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle null or special keyword
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip().lower()
    else:
        raise ValueError("Frequency must be a string or None")
    if freq_str == "always":
        return None

    # Define mapping from unit to timedelta keyword
    unit_map = {
        'second': 'seconds',
        'seconds': 'seconds',
        'minute': 'minutes',
        'minutes': 'minutes',
        'hour': 'hours',
        'hours': 'hours',
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
    }

    # Attempt to parse number and unit
    parts = freq_str.split()
    if not parts:
        raise ValueError(f"Invalid frequency format: '{frequency}'")
    # If the string contains no space, try to separate numeric part from unit part
    if len(parts) == 1:
        part = parts[0]
        # Find transition from digits to letters
        i = 0
        while i < len(part) and part[i].isdigit():
            i += 1
        if i == 0 or i == len(part):
            raise ValueError(f"Invalid frequency format: '{frequency}'")
        num_part = part[:i]
        unit_part = part[i:]
    else:
        num_part, unit_part = parts[0], parts[1]

    try:
        amount = int(num_part)
    except ValueError:
        raise ValueError(f"Frequency amount must be an integer: '{num_part}' in '{frequency}'")

    unit_kw = unit_map.get(unit_part.lower())
    if unit_kw is None:
        raise ValueError(f"Unknown time unit '{unit_part}' in frequency '{frequency}'")
    kwargs = {unit_kw: amount}
    try:
        return datetime.timedelta(**kwargs)
    except Exception as e:
        raise ValueError(f"Failed to create timedelta from frequency '{frequency}': {e}")<|return|>

