    if not h:
        return False

    # Quick known loopback checks
    if h in ("localhost", "127.0.0.1", "::1"):
        return True

    try:
        host_addrinfo = socket.getaddrinfo(h, None, 0, socket.SOCK_STREAM)
    except socket.gaierror:
        # If the host cannot be resolved, it cannot be local
        return False

    try:
        local_addrinfo = socket.getaddrinfo(socket.gethostname(), None, 0, socket.SOCK_STREAM)
    except socket.gaierror:
        local_addrinfo = []

    # Build a set of local IP addresses
    local_ips = set()
    for family, _, _, _, sockaddr in local_addrinfo:
        if family == socket.AF_INET:
            local_ips.add(sockaddr[0])  # IPv4 address
        elif family == socket.AF_INET6:
            local_ips.add(sockaddr[0])  # IPv6 address

    # Include standard loopback addresses
    local_ips.update({"127.0.0.1", "::1"})

    # Check if any resolved address of the input host matches a local address
    for family, _, _, _, sockaddr in host_addrinfo:
        try:
            addr = sockaddr[0]
        except (IndexError, TypeError):
            continue
        if addr in local_ips:
            return True

    return False<|return|>

