def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Normalise matcher to (name, default) tuple
    if matcher is None:
        raise ValueError("Matcher cannot be None")
    if isinstance(matcher, (list, tuple)):
        if not matcher:
            raise ValueError("Matcher must contain at least one element")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        # Treat the matcher as a simple name string
        name = matcher
        default = None

    if not isinstance(name, str):
        raise TypeError(f"Environment variable name must be a string, got {type(name).__name__}")

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise RuntimeError(f"Environment variable '{name}' not defined and no default provided")
    return value<|return|>

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern.
    It supports '*' as any sequence of characters and '?' as any single character.
    If strip is True, leading and trailing whitespace is removed.
    Returns a compiled re.Pattern object.
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if strip:
        pattern = pattern.strip()
    # Escape all regex special characters, but keep wildcards
    escaped = re.escape(pattern)
    # Replace escaped wildcard tokens with regex equivalents
    escaped = escaped.replace(r'\*', '.*').replace(r'\?', '.')
    try:
        return re.compile(escaped)
    except re.error as exc:
        raise ValueError(f"Could not compile regex from pattern: {pattern}") from exc<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os, sys, shlex

    # Build the list of command components
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        cmd.extend(args)

    if verbose:
        # Pretty-print the full command for debugging
        formatted = " ".join(shlex.quote(part) for part in cmd)
        print(f"Running command: {formatted}")

    # Merge environment variables
    run_env = os.environ.copy()
    if env:
        run_env.update(env)

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=run_env,
            capture_output=True,
            text=True
        )
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {cmd[0]}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error running command {cmd[0]}: {exc}") from exc

    # Optionally write stderr to sys.stderr
    if not hide_stderr and result.stderr:
        sys.stderr.write(result.stderr)

    return result<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Prepare command list
    try:
        if isinstance(commands, (list, tuple)):
            base_cmd = list(commands)
        else:
            # If commands is a string, split on whitespace unless already a list
            base_cmd = [commands]
        if not isinstance(args, (list, tuple)):
            raise ValueError("args must be a list/tuple of arguments")
        full_cmd = base_cmd + list(args)
        # Set up stderr redirection
        stderr_target = subprocess.DEVNULL if hide_stderr else None
        # Launch subprocess
        proc = subprocess.Popen(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True
        )
        stdout, _ = proc.communicate()
        if verbose:
            print(stdout, end='')
        if proc.returncode != 0:
            raise subprocess.CalledProcessError(proc.returncode, full_cmd, output=stdout)
        return proc.returncode
    except FileNotFoundError:
        if verbose:
            print(f"Command not found: {commands}")
        raise
    except Exception as exc:
        if verbose:
            print(f"Error running command {commands}: {exc}")
        raise
