                # Treat dumper as a Dumper class for yaml.dump
                def wrapper(o):
                    return yaml.dump(
                        o,
                        Dumper=dumper,
                        default_flow_style=False,
                        allow_unicode=True,
                    )
                dump_func = wrapper

        # Perform the dump
        result = dump_func(
            obj, default_flow_style=False, allow_unicode=True
        )
        # yaml.safe_dump returns string in py3, but may return bytes in some builds
        if isinstance(result, bytes):
            try:
                result = result.decode("utf-8")
            except Exception as exc:
                raise ValueError(
                    f"Failed to decode YAML dump to string: {exc}"
                ) from exc
        if result is None:
            raise ValueError("The dumper returned None instead of a string.")
        # In Py2 ensure we have a unicode string
        if isinstance(result, str):
            try:
                # In Python 2, str is bytes; try to convert to unicode
                # Only attempt conversion if not already unicode
                if not isinstance(result, unicode):  # noqa: F821
                    result = unicode(result, "utf-8")  # noqa: F821
            except Exception:
                # If conversion fails, leave as is (bytes) which is acceptable in Py2
                pass
        return result
    except yaml.YAMLError as exc:
        raise ValueError(f"Error dumping object to YAML string: {exc}") from exc
    except Exception as exc:
        raise ValueError(f"Unexpected error during YAML dump: {exc}") from exc<|return|>

