def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        # Convert input to a NumPy array of floats for vectorized computation
        x_arr = np.asarray(x, dtype=float)
    except Exception as exc:
        raise ValueError("`x` must be convertible to a numeric type.") from exc

    mu = 0.2
    sigma = 0.1
    try:
        # Compute the Gaussian function
        result = np.exp(-((x_arr - mu) ** 2) / (2 * sigma ** 2))
    except Exception as exc:
        # Catch any arithmetic issues (e.g., invalid subtraction) and raise a clearer error
        raise ValueError("Failed to compute Gaussian: input may contain unsupported non-numeric values.") from exc

    # If the result is a zero‑dimensional array, return a plain Python float
    if np.ndim(result) == 0:
        return float(result)
    return result<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import re
    errors = []
    configs = {}

    def _record_error(msg, exc=None):
        # Create a LogRecord with ERROR level and given message
        exc_info = exc if exc is not None else None
        record = logging.LogRecord(
            name=__name__,
            level=logging.ERROR,
            pathname='',
            lineno=0,
            msg=msg,
            args=(),
            exc_info=exc_info
        )
        errors.append(record)

    def _resolve_env(obj):
        """Recursively resolve environment variables in a dict or list."""
        if isinstance(obj, dict):
            return {k: _resolve_env(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env(v) for v in obj]
        if isinstance(obj, str):
            # Replace ${VAR} or ${VAR:default}
            pattern = re.compile(r'\${([^}]+)}')
            def repl(m):
                expr = m.group(1)
                if ':' in expr:
                    var, default = expr.split(':', 1)
                    return os.getenv(var, default)
                return os.getenv(expr, '')
            return pattern.sub(repl, obj)
        return obj

    def _deep_merge(target, src):
        """Recursively merge src dict into target dict."""
        for key, value in src.items():
            if key in target and isinstance(target[key], dict) and isinstance(value, dict):
                _deep_merge(target[key], value)
            else:
                target[key] = value

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as e:
            _record_error(f'Failed to read configuration file: {fname}', exc=e)
            continue

        try:
            parsed = json.loads(content)
        except Exception as e:
            _record_error(f'JSON parsing error in file: {fname}', exc=e)
            continue

        if not isinstance(parsed, dict):
            _record_error(f'Configuration in {fname} is not a dictionary')
            continue

        if resolve_env:
            try:
                parsed = _resolve_env(parsed)
            except Exception as e:
                _record_error(f'Environment resolution error in file: {fname}', exc=e)
                continue

        if overrides:
            try:
                _deep_merge(parsed, overrides)
            except Exception as e:
                _record_error(f'Override application error for file: {fname}', exc=e)
                continue

        configs[fname] = parsed

    return configs, errors<|return|>

import os
import re
import json
import logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    if config_filenames is None:
        raise TypeError("config_filenames must be a non‑empty sequence")
    if not hasattr(config_filenames, "__iter__"):
        raise TypeError("config_filenames must be iterable")
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError("overrides must be a dictionary or None")

    configs = {}
    errors = []

    def _replace_env(value):
        """Recursively replace ${VAR} placeholders in strings using os.getenv."""
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return re.sub(r'\${([^}]+)}', repl, value)
        elif isinstance(value, dict):
            return {k: _replace_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_replace_env(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        if not isinstance(filename, str):
            # Skip non-string filenames
            continue
        try:
            with open(filename, 'r') as f:
                raw = f.read()
        except Exception as exc:
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to open configuration file '{filename}': {exc}",
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        try:
            config = json.loads(raw)
        except Exception as exc:
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to parse JSON in configuration file '{filename}': {exc}",
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        # Resolve environment variables if requested
        if resolve_env:
            config = _replace_env(config)

        # Apply overrides if provided
        if overrides:
            if isinstance(config, dict):
                for key, val in overrides.items():
                    config[key] = val
            # If config is not a dict, we cannot apply overrides
            else:
                record = logging.LogRecord(
                    name=__name__,
                    level=logging.WARNING,
                    pathname=filename,
                    lineno=0,
                    msg=f"Overrides not applied because configuration in '{filename}' is not a dict",
                    args=(),
                    exc_info=None
                )
                errors.append(record)

        configs[filename] = config

    return (configs, errors)<|return|>

