@classmethod
    def from_ticks(cls, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        # Validate type
        if not isinstance(ticks, int):
            raise TypeError(f"ticks must be an integer, got {type(ticks).__name__}")
        # Bounds check
        if ticks < 0 or ticks >= 86400000000000:
            raise ValueError("ticks is out of bounds: must be 0 <= ticks < 86400000000000")
        # Break down ticks into components
        try:
            total_seconds, nano_rem = divmod(ticks, 1_000_000_000)
            hour, rem = divmod(total_seconds, 3600)
            minute, second = divmod(rem, 60)
        except Exception as e:
            raise RuntimeError(f"Failed to decompose ticks: {e}") from e

        # Attempt to create an instance with nanosecond resolution
        try:
            # First try the most common signature: (hour, minute, second, nanosecond, tzinfo=None)
            return cls(hour, minute, second, nano_rem, tzinfo=tz)
        except TypeError:
            # Fallback: perhaps the constructor accepts microseconds instead of nanoseconds
            try:
                micro, nanosec_remainder = divmod(nano_rem, 1000)
                return cls(hour, minute, second, micro, tzinfo=tz)
            except Exception as exc:
                # If we cannot construct a proper instance, propagate an informative error
                raise RuntimeError("Unable to construct Time instance from ticks: the "
                                   "provided constructor does not accept the expected "
                                   "parameters.") from exc
        except Exception as exc:
            # Any other unexpected error during construction
            raise RuntimeError(f"Error constructing Time instance: {exc}") from exc<|return|>

