def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        # Import dependencies locally to keep function self-contained
        import base64
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding, ec
        from cryptography.exceptions import InvalidSignature

        # Normalize public key input
        if isinstance(public_key, bytes):
            key_bytes = public_key
        else:
            key_bytes = str(public_key).encode("utf-8")

        # Attempt to load PEM public key, fallback to DER
        try:
            pub_key = serialization.load_pem_public_key(key_bytes)
        except ValueError:
            pub_key = serialization.load_der_public_key(key_bytes)

        # Prepare message bytes
        if isinstance(doc, bytes):
            message = doc
        else:
            message = str(doc).encode("utf-8")

        # Decode signature; accept base64 or hex
        sig_bytes = None
        for decode_func in (base64.b64decode, lambda s: bytes.fromhex(s)):
            try:
                sig_bytes = decode_func(signature)
                break
            except Exception:
                continue
        if sig_bytes is None:
            return False

        # Perform verification depending on key type
        if isinstance(pub_key, ec.EllipticCurvePublicKey):
            pub_key.verify(sig_bytes, message, ec.ECDSA(hashes.SHA256()))
        else:
            pub_key.verify(sig_bytes, message, padding.PKCS1v15(), hashes.SHA256())

        return True
    except (ValueError, TypeError, InvalidSignature, Exception):
        # Return False on any verification or parsing error
        return False<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            subject = data.get("subject")
            links = data.get("links", [])
            # Ensure links is a list of dicts
            if not isinstance(links, list):
                links = []
            return {"subject": subject, "links": links}
    except json.JSONDecodeError:
        pass  # Fall back to XML parsing

    try:
        root = ElementTree.fromstring(document)
        # Find subject element (namespace‑agnostic)
        subject_elem = root.find(".//{*}Subject")
        subject = subject_elem.text if subject_elem is not None else None

        # Gather all link elements
        links: list[dict] = []
        for link_elem in root.findall(".//{*}Link"):
            rel = link_elem.attrib.get("rel")
            href = link_elem.attrib.get("href")
