def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _parse_json(d: str):
        try:
            data = json.loads(d)
            result = {}
            # Subject
            if "subject" in data:
                result["subject"] = data["subject"]
            # Aliases
            aliases = data.get("aliases")
            if isinstance(aliases, list):
                result["aliases"] = aliases
            # Links
            links = data.get("links")
            if isinstance(links, list):
                result["links"] = links
            return result
        except (json.JSONDecodeError, TypeError):
            return None

    def _parse_xrd(d: str):
        try:
            root = ET.fromstring(d)
        except ET.ParseError:
            return None

        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        result = {}
        # Subject
        subject = root.find("xrd:Subject", ns)
        if subject is not None and subject.text:
            result["subject"] = subject.text

        # Aliases
        aliases = []
        for alias in root.findall("xrd:Alias", ns):
            if alias.text:
                aliases.append(alias.text)
        if aliases:
            result["aliases"] = aliases

        # Links
        links = []
        for link in root.findall("xrd:Link", ns):
            link_dict = {}
            # Gather all attributes that might be relevant
            for attr in ("rel", "type", "href", "template"):
                if attr in link.attrib:
                    link_dict[attr] = link.attrib[attr]
            # Also include any additional attributes
            for k, v in link.attrib.items():
                if k not in link_dict:
                    link_dict[k] = v
            if link_dict:
                links.append(link_dict)
        if links:
            result["links"] = links

        return result

    # Try JSON first
    parsed = _parse_json(document)
    if parsed is not None:
        return parsed

    # Fallback to XRD parsing
    parsed = _parse_xrd(document)
    if parsed is not None:
        return parsed

    # If both fail, return empty dict
    return {}<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
