        aliases = []
        for alias in root.findall('Alias'):
            if alias.text:
                aliases.append(alias.text.strip())
        # Namespaced aliases
        for alias in root.findall('xrd:Alias', {'xrd': 'http://xrd.info/schemas/xrd'}):
            if alias.text:
                aliases.append(alias.text.strip())
        if aliases:
            result['aliases'] = aliases

        # Links
        for link in root.findall('Link'):
            rel = link.attrib.get('rel')
            href = link.attrib.get('href')
            if rel and href:
                result[rel] = href
        # Namespaced links
        for link in root.findall('xrd:Link', {'xrd': 'http://xrd.info/schemas/xrd'}):
            rel = link.attrib.get('rel')
            href = link.attrib.get('href')
            if rel and href:
                result[rel] = href

        return result

    # Attempt JSON parsing first
    try:
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger is not a dict")
        result: Dict = {}
        # Subject
        if 'subject' in data:
            result['subject'] = str(data['subject'])
        # Aliases
        if 'aliases' in data and isinstance(data['aliases'], list):
            result['aliases'] = [str(a) for a in data['aliases']]
        # Links
        for link in data.get('links', []):
            if not isinstance(link, dict):
                continue
            rel = link.get('rel')
            href = link.get('href')
            if rel and href:
                result[rel] = str(href)
