    try:
        import xml.etree.ElementTree as ET

        def _localname(qname: str) -> str:
            return qname.split('}', 1)[-1] if '}' in qname else qname

        root = ET.fromstring(document)
        result: Dict = {}

        # Extract Subject
        subject = None
        for child in root:
            if _localname(child.tag) == 'Subject':
