        if subject:
            result['subject'] = subject

        # Extract Aliases
        aliases = []
        for child in root:
            if _localname(child.tag) == 'Alias' and child.text:
                aliases.append(child.text.strip())
        if aliases:
            result['aliases'] = aliases

        # Extract Links
        links = []
        for child in root:
            if _localname(child.tag) == 'Link':
                entry: Dict = {}
                for attr in ('rel', 'type', 'href', 'template', 'title'):
                    val = child.get(attr)
                    if val:
                        entry[attr] = val
                if entry:
                    links.append(entry)
        if links:
            result['links'] = links

        return result
    except Exception:
        pass

    # If all parsing fails, return empty dict
    return {}<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Input document must be a non-empty string")

    # First, try to parse as JSON
    try:
        import json
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must represent an object")
