        handle = handle.strip()
        if not handle or '@' not in handle:
            return None
        local_part, domain = handle.split('@', 1)
        if not local_part or not domain:
            return None
        resource = f'acct:{local_part}@{domain}'
        url = f'https://{domain}/.well-known/webfinger?resource={resource}'
        try:
            # Attempt to use requests if available
            response = requests.get(url, timeout=5)
            if response.status_code == 200:
                return response.text
        except NameError:
            # requests not available; try urllib as fallback
            try:
