    if not isinstance(handle, str) or '@' not in handle:
        return None

    try:
        import urllib.request
        import urllib.parse
    except Exception:
        return None

    user, domain = handle.split('@', 1)
    # Encode resource key
    resource = urllib.parse.quote(f"acct:{handle}")
    url = f"https://{domain}/.well-known/webfinger?resource={resource}"

    # Prepare request with a standard Accept header
    req = urllib.request.Request(
        url,
        headers={"Accept": "application/json"},
        method="GET"
