    try:
        with urllib.request.urlopen(req, timeout=5) as response:
            if 200 <= response.getcode() < 300:
                return response.read().decode("utf-8", errors="ignore")
    except Exception:
        # Any failure results in no data returned
        return None

    return None<|return|>

