def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        import requests
    except ImportError as e:
        return (None, e)

    # Ensure method is a case-insensitive string
    if not isinstance(method, str):
        return (None, TypeError(f"method must be a string, got {type(method).__name__}"))

    try:
        # Dispatch to the appropriate requests function
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            # For other methods, use the generic request interface
            response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)

        # If the request succeeded, return the status code
        return (response.status_code, None)
    except Exception as exc:
        # Capture any exception (including network issues, timeouts, etc.)
        return (None, exc)<|return|>

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post`` or the method specified.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    import requests  # Assume requests is available in the caller's namespace

    # Validate inputs
    if not isinstance(url, str) or not url:
        return None, ValueError("url must be a non-empty string")

    if timeout is not None:
        try:
            timeout = float(timeout)
        except Exception:
            return None, ValueError("timeout must be a number")

    # Determine the HTTP method to use
    method_name = (method or "post").lower()
    try:
        http_method = getattr(requests, method_name)
    except AttributeError:
        return None, ValueError(f"Unsupported HTTP method: {method_name!r}")

    if not callable(http_method):
        return None, ValueError(f"HTTP method {method_name!r} is not callable")

    try:
        # Send the request
        response = http_method(url, data=data, timeout=timeout, *args, **kwargs)
        return response.status_code, None
    except Exception as exc:
        # Return the exception instance so the caller can examine it
        return None, exc<|return|>

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Validate input types
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if not isinstance(key, str):
        raise TypeError("key must be a string")
    for k in keys:
        if not isinstance(k, str):
            raise TypeError("all keys must be strings")

    # Build the full list of keys
    all_keys = [key] + list(keys)
    if not all_keys:
        raise ValueError("At least one key must be provided")

    current = dic
    # Traverse or create intermediate dictionaries
    for intermediate_key in all_keys[:-1]:
        if intermediate_key not in current:
            current[intermediate_key] = {}
        else:
            if not isinstance(current[intermediate_key], dict):
                raise TypeError(f"Cannot insert into non-dict at key '{intermediate_key}'")
        current = current[intermediate_key]

    # Set the final key to the value
    current[all_keys[-1]] = val
    return dic<|return|>

