    else:
        try:
            iter(settings_dirs)
        except TypeError:
            raise TypeError('settings_dirs must be a string or iterable of strings')
        dirs = list(settings_dirs)

    # Helper to decide if a file name matches the spec_option
    def _matches(name):
        if spec_option is None:
            return True
        # Callable spec_option
        if callable(spec_option):
            try:
                return bool(spec_option(name))
            except Exception:
                return False
        # Iterable of patterns
