    """Create a new IniType complex type"""
    # Use dynamic import to avoid top‑level import statements
    try:
        os = __import__('os')
    except Exception as exc:
        # If os cannot be imported, there is nothing we can do
        raise RuntimeError("Required module 'os' could not be imported") from exc

    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple, set)):
        dirs = list(settings_dirs)
    else:
        raise TypeError("settings_dirs must be a string or a list/tuple of directory paths")

    # Accept None or empty string for spec_option and treat as no filter
    filter_ext = None
    if isinstance(spec_option, str) and spec_option:
        filter_ext = spec_option
    elif spec_option is not None:
        # If spec_option is not None but not a string, attempt to convert
        try:
            filter_ext = str(spec_option)
        except Exception:
            filter_ext = None

    file_names = []
    for dir_path in dirs:
        if not isinstance(dir_path, (str, bytes)):
            # Skip non‑string paths
            continue
        if not os.path.isdir(dir_path):
            # Directory does not exist; skip and continue gracefully
            continue
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    if filter_ext is None or entry.endswith(filter_ext):
                        file_names.append(full_path)
        except Exception:
            # Skip directories that cause any exception (permissions, etc.)
            continue

    return file_names

