@classmethod
def ansible_config_manager(cls):
    """Gets the ansible config manager."""
    # Return cached config if available
    if hasattr(cls, "_ansible_config_cache"):
        return cls._ansible_config_cache

    try:
        import os
        import configparser

        # Determine the config file path
        config_path = os.environ.get("ANSIBLE_CONFIG")
        if not config_path:
            # Default search order: current dir, then system default
            cwd_cfg = os.path.join(os.getcwd(), "ansible.cfg")
            if os.path.isfile(cwd_cfg):
                config_path = cwd_cfg
            else:
                config_path = "/etc/ansible/ansible.cfg"

        parser = configparser.ConfigParser()
        read_files = parser.read(config_path)
        if not read_files:
            # No config file found; return empty dict
            cls._ansible_config_cache = {}
            return {}

        # Convert sections to a simple dictionary
        config_dict = {section: dict(parser.items(section)) for section in parser.sections()}
        cls._ansible_config_cache = config_dict
        return config_dict

    except (configparser.Error, OSError, Exception) as exc:
        # If any error occurs (file missing, parse error, permission), log it and return empty dict
        # Normally we'd log the exception; for safety we don't output it.
        cls._ansible_config_cache = {}
        return {}<|return|>

