@classmethod
def validate_from_content(cls, spec_content=None):
    """
    Validates that spec (YAML) content has all required fields.

    :param spec_content: content of spec file (YAML string)
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    try:
        import yaml
    except Exception as exc:
        raise IRValidatorException(f"Missing yaml parser: {exc}") from exc

    try:
        data = yaml.safe_load(spec_content)
    except Exception as exc:
        raise IRValidatorException(f"Failed to parse YAML: {exc}") from exc

    if not isinstance(data, dict):
        raise IRValidatorException("Spec content does not contain a YAML mapping")

    # Define required top‑level keys for a typical Kubernetes spec
    required_top_keys = ["apiVersion", "kind", "metadata", "spec"]
    for key in required_top_keys:
        if key not in data:
            raise IRValidatorException(f"Missing required key '{key}' in spec")

    # Ensure metadata contains a name (and optionally namespace)
    metadata = data.get("metadata", {})
    if not isinstance(metadata, dict):
        raise IRValidatorException("metadata section must be a mapping")
    if "name" not in metadata or not metadata["name"]:
        raise IRValidatorException("metadata.name is required and must be non‑empty")

    # Optional: also check namespace if present
    if "namespace" in metadata and not metadata["namespace"]:
        raise IRValidatorException("metadata.namespace must be non‑empty if provided")

    return data<|return|>

