def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    import yaml

    def deep_merge(source, destination):
        """
        Recursively merge source dict into destination dict.
        Values in source override those in destination when conflicts occur.
        """
        for key, value in source.items():
            if isinstance(value, dict) and isinstance(destination.get(key), dict):
                deep_merge(value, destination[key])
            else:
                destination[key] = value

    # Grab the include definitions, if any.
    includes = parser_dict.get("include")
    if not includes:
        return parser_dict

    # Ensure we always work with a list of include items.
    if not isinstance(includes, list):
        includes = [includes]

    for inc in includes:
        try:
            # Each include can be a path string, a file dict, or a nested dict.
            if isinstance(inc, dict):
                # If the dict contains a file path, we load that file.
                for sub_key, sub_val in inc.items():
                    if isinstance(sub_val, str):
                        with open(sub_val, "r", encoding="utf-8") as f:
                            inc_dict = yaml.safe_load(f)
                        deep_merge(inc_dict, parser_dict)
                    else:
                        # Merge any nested dictionary directly.
                        deep_merge(sub_val, parser_dict)
            elif isinstance(inc, str):
                with open(inc, "r", encoding="utf-8") as f:
                    inc_dict = yaml.safe_load(f)
                deep_merge(inc_dict, parser_dict)
            else:
                # Unsupported include format; skip gracefully.
                continue
        except Exception as exc:
            raise RuntimeError(f"Error including spec {inc!r}") from exc

    # Clean up the directive once processed.
    parser_dict.pop("include", None)
    return parser_dict<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    try:
        include_key = "_include"
        if include_key not in parser_dict:
            return parser_dict

        include_def = parser_dict.pop(include_key)

        # If the include definition is a path to a file, try to load it as JSON.
        if isinstance(include_def, str):
            try:
                import os
                import json
                path = os.path.abspath(include_def)
                if not os.path.isfile(path):
                    raise FileNotFoundError(f"Include file not found: {path}")
                with open(path, "r", encoding="utf-8") as f:
                    include_data = json.load(f)
                if isinstance(include_data, dict):
                    parser_dict.update(include_data)
                else:
                    raise ValueError(f"Included file {path} does not contain a dictionary.")
            except Exception as e:
                # The file could not be read; treat the string as a literal key if it's a dict embed.
                raise ValueError(f"Failed to include file '{include_def}': {e}")

        # If the include definition is a dictionary, merge it.
        elif isinstance(include_def, dict):
            parser_dict.update(include_def)

        # If it is a list of dictionaries, merge each item.
        elif isinstance(include_def, list):
            for item in include_def:
                if isinstance(item, dict):
                    parser_dict.update(item)
                else:
                    raise ValueError("Include list contains non-dictionary elements.")
        else:
            raise TypeError("Include definition must be a dict, list, or path string.")
        return parser_dict
    except Exception as exc:
        raise RuntimeError(f"Error resolving include groups: {exc}") from exc<|return|>

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files.

        The method looks for an ``include`` key inside the supplied ``parser_dict``.  
        The value is expected to be a mapping whose values are group names that must be
        resolved against the ``groups`` mapping present in the same dictionary.  
        Each referenced group is merged into the top‑level ``parser_dict`` – keys that
        already exist in ``parser_dict`` are overridden; this behaviour can be tuned
        by adjusting the ``override`` flag below.

        If a group cannot be found or is not a mapping, a descriptive ``KeyError`` /
        ``TypeError`` is raised.  The input dictionary is modified in place and ``None``
        is returned for convenience.
        """
        if not isinstance(parser_dict, dict):
            raise TypeError(f"_include_groups expects a dict, got {type(parser_dict).__name__}")

        includes = parser_dict.get("include")
        if includes is None:
            # Nothing to include – silently succeed
            return
        if not isinstance(includes, dict):
            raise TypeError(
                f"The 'include' key must contain a mapping, got {type(includes).__name__}"
            )

        # Retrieve the groups definitions; they must exist in the same dict
        groups = parser_dict.get("groups", {})
        if not isinstance(groups, dict):
            raise TypeError(
                f"The 'groups' key must contain a mapping, got {type(groups).__name__}"
            )

        for key, group_name in includes.items():
            if not isinstance(group_name, str):
                raise TypeError(
                    f"Group name for key '{key}' must be a string, got {type(group_name).__name__}"
                )
            group_def = groups.get(group_name)
            if group_def is None:
                raise KeyError(
                    f"Included group '{group_name}' (requested by key '{key}') not found in 'groups'"
                )
            if not isinstance(group_def, dict):
                raise TypeError(
                    f"Group '{group_name}' should be a dict, got {type(group_def).__name__}"
                )

            # Merge the group into the top–level dictionary
            # Keys from the group override existing keys – this behaviour can be changed if needed
            for gk, gv in group_def.items():
                try:
                    # If the key already exists, we try to merge nested dicts recursively
                    existing = parser_dict.get(gk)
                    if isinstance(existing, dict) and isinstance(gv, dict):
                        # Recursive merge – simple shallow copy of nested dict
                        merged = existing.copy()
                        merged.update(gv)
                        parser_dict[gk] = merged
                    else:
                        parser_dict[gk] = gv
                except Exception as exc:
                    raise RuntimeError(
                        f"Failed to merge key '{gk}' from group '{group_name}'"
                    ) from exc

        # Optionally, remove the 'include' and 'groups' keys after resolution
        # Uncomment if you want to clean up the dictionary after processing:
        # parser_dict.pop("include", None)
        # parser_dict.pop("groups", None)
        return None<|return|>

