def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Extract arguments section from the instance's spec.
    try:
        spec = getattr(self, "spec", {})
        if not isinstance(spec, dict):
            raise TypeError("'spec' attribute must be a dictionary")
        args = spec.get("arguments") or spec.get("args") or {}
        if not isinstance(args, dict):
            raise TypeError("'arguments' section must be a dictionary")
    except Exception as exc:
        raise RuntimeError(f"Invalid spec structure: {exc}") from None

    defaults = {}
    for name, cfg in args.items():
        try:
            # Determine the default value declared in the spec.
            if isinstance(cfg, dict):
                default = cfg.get("default")
            else:
                # If the spec entry is a primitive, treat it as a default.
                default = cfg

            # Allow an environment variable override. Example: CLASSNAME_ARGNAME
            env_key = f"{self.__class__.__name__.upper()}_{name.upper()}"
            env_val = os.getenv(env_key)
            if env_val is not None:
                # Convert the env value to the type of the default if possible.
                if default is not None:
                    try:
                        env_val = type(default)(env_val)
                    except Exception:
                        pass
                default = env_val

            defaults[name] = default
        except Exception:
            # Skip problematic entries without halting the whole process.
            continue

    # Merge any instance‑level defaults that may have been set elsewhere.
    try:
        instance_defaults = getattr(self, "defaults", {})
        if isinstance(instance_defaults, dict):
            defaults.update(instance_defaults)
    except Exception:
        pass

    return defaults<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Initialize an empty dictionary for defaults
    defaults = {}
    # Attempt to retrieve the spec dictionary; silently return empty if not present
    spec = getattr(self, "spec", None)
    if not isinstance(spec, dict):
        return defaults
    # Iterate over each item in the spec and resolve the default value
    for key, value in spec.items():
        try:
            # If the spec entry is a mapping, look for 'default', 'env', or 'file'
            if isinstance(value, dict):
                # Explicit default value
                if "default" in value:
                    defaults[key] = value["default"]
                # Value from an environment variable
                elif "env" in value:
                    env_var = value["env"]
                    imports_needed = ["os"]
                    # Import required modules on the fly
                    for module_name in imports_needed:
                        __import__(module_name)
                    defaults[key] = os.getenv(env_var)
                # Value loaded from a configuration file
                elif "file" in value:
                    file_path = value["file"]
                    try:
                        __import__("json")
                        with open(file_path, "r") as f:
                            config_data = json.load(f)
                        defaults[key] = config_data.get(key)
                    except Exception as e:
                        # If reading the file fails, log the error and continue
                        try:
                            import logging
                            logger = logging.getLogger(__name__)
                            logger.warning(
                                "Failed to load default for '%s' from file '%s': %s",
                                key,
                                file_path,
                                e,
                            )
                        except Exception:
                            pass
                        defaults[key] = None
                else:
                    defaults[key] = None
            else:
                # If the spec entry is not a dict, use it directly as the default
                defaults[key] = value
        except Exception as exc:
            # Catch any unexpected error and log it so the process continues
            try:
                import logging

                logger = logging.getLogger(__name__)
                logger.error("Error resolving default for '%s': %s", key, exc)
            except Exception:
                pass
            defaults[key] = None
    return defaults<|return|>

