def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate inputs
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string.")
    if not isinstance(argument_name, str) or not argument_name:
        raise ValueError("argument_name must be a non-empty string.")

    # Attempt to locate the command specifications dictionary
    spec_dict = getattr(self, "commands", None)
    if spec_dict is None:
        spec_dict = getattr(self, "specs", {})
    if not isinstance(spec_dict, dict):
        raise TypeError("Command specifications should be stored in a dictionary attribute 'commands' or 'specs'.")

    # Retrieve the command specification
    command_spec = spec_dict.get(command_name)
    if command_spec is None:
        raise KeyError(f"Command '{command_name}' not found in specifications.")

    # The command specification should contain an 'arguments' mapping
    if isinstance(command_spec, dict):
        arguments = command_spec.get("arguments", {})
    else:
        # Fallback for objects with an 'arguments' attribute
        arguments = getattr(command_spec, "arguments", {})

    if not isinstance(arguments, dict):
        raise TypeError(f"The 'arguments' of command '{command_name}' must be a dictionary.")

    # Retrieve the specific argument specification
    option_spec = arguments.get(argument_name)
    if option_spec is None:
        raise KeyError(f"Argument '{argument_name}' not found for command '{command_name}'.")

