def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    try:
        # If args is not provided or is not a mapping, return empty list.
        if args is None:
            return []

        # When args is a dictionary: return keys that start with an underscore.
        if isinstance(args, dict):
            return [key for key in args if isinstance(key, str) and key.startswith('_')]

        # If args is a list or tuple of key/value pairs, attempt to extract keys.
        if isinstance(args, (list, tuple)):
            silent_keys = []
            for item in args:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    key, _ = item
                    if isinstance(key, str) and key.startswith('_'):
                        silent_keys.append(key)
            return silent_keys

        # Unsupported type: return an empty list.
        return []

    except Exception:
        # In case of any unexpected error, return an empty list to avoid breaking callers.
        return []<|return|>

def get_silent_args(self, args):
    """
