    silent_names = []

    try:
        # Handle mapping types directly (e.g., dict, collections.OrderedDict)
        if isinstance(args, dict):
            for key in args:
                if isinstance(key, str) and key.startswith('_'):
                    silent_names.append(key)

        # Handle iterable of key/value pairs, e.g., list of tuples or list of dicts
        elif hasattr(args, '__iter__'):
            for item in args:
                # If item is a mapping itself
                if isinstance(item, dict):
                    for key in item:
                        if isinstance(key, str) and key.startswith('_'):
                            silent_names.append(key)
                # If item is a key/value pair
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    key, _ = item
                    if isinstance(key, str) and key.startswith('_'):
                        silent_names.append(key)

        # Fallback for objects that expose a ``keys`` method (e.g., argparse.Namespace)
        elif hasattr(args, 'keys'):
            for key in args.keys():
                if isinstance(key, str) and key.startswith('_'):
                    silent_names.append(key)

    except Exception:
        # If any unexpected error occurs, return an empty list to avoid breaking callers
        return []

    # Ensure unique names only if args may contain duplicates
    return list(dict.fromkeys(silent_names))
