def get_silent_args(self, args):
    """
    Retrieve the names of arguments that are considered "silenced" (i.e., have falsy values).

    Parameters
    ----------
    args : Mapping or Iterable
        The received arguments. Expected to be a mapping (e.g., dict) or an iterable of (key, value) pairs.

    Returns
    -------
    list
        A list containing the names of arguments whose associated values evaluate to falsy.
    """
    silent_keys = []

    try:
        # Handle mapping types (e.g., dict, defaultdict)
        if hasattr(args, "items") and callable(args.items):
            for key, value in args.items():
                if not value:
                    silent_keys.append(str(key))
        # Handle iterables of key/value pairs (e.g., list of tuples)
        else:
            for item in args:
                if not isinstance(item, (list, tuple)) or len(item) != 2:
                    continue  # skip malformed entries
                key, value = item
                if not value:
                    silent_keys.append(str(key))
    except Exception:
        # In case of any unexpected error, fall back to an empty list
        return []

    # Return a sorted list for deterministic output
    return sorted(silent_keys)<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    try:
        # Get the list/set of required argument names from common attribute names
        required = getattr(self, 'required_args', None)
        if required is None:
            required = getattr(self, 'REQUIRED_ARGS', None)
        # If no required argument list defined, nothing to check
        if not required:
            return True

        missing = []

        # If args is a dict, validate by key presence and non‑None value
        if isinstance(args, dict):
            for key in required:
                if key not in args or args[key] is None:
                    missing.append(key)

        # Otherwise treat args as a sequence (list/tuple) of positional arguments.
        # In that case required is expected to be an iterable of argument names or a) indexes.
        else:
            # If required list contains indexes (integers), use them.
            if all(isinstance(k, int) for k in required):
                for idx in required:
                    try:
                        if idx >= len(args) or args[idx] is None:
                            missing.append(idx)
                    except Exception:
                        missing.append(idx)
            # If required list contains string names but args is not a dict,
            # we cannot reliably check; treat each missing name as missing.
            else:
                missing.extend(required)

        if missing:
            # Format missing for clarity
            missing_repr = ', '.join(str(m) for m in missing)
            raise ValueError(f"Missing required arguments: {missing_repr}")

        return True

    except Exception:
        # Re‑raise any unexpected exceptions to preserve traceback context
        raise

