def _get_conditionally_required_args(self, command_name, options_spec,
                                      args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Ensure we have a sane input structure
    if not isinstance(options_spec, (list, tuple)):
        return []

    # Normalise args to a dictionary for key lookup
    if args is None:
        args = {}
    elif not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}

    required_names = set()

    for option in options_spec:
        # Expect each option to be dict‑like; skip otherwise
        if not isinstance(option, dict):
            continue

        # Retrieve the name of the argument/option
        name = option.get("name") or option.get("arg") or option.get("key")
        if not name:
            continue

        # Skip if there is no conditional requirement info
        if "required_when" not in option:
            continue

        required_when = option["required_when"]

        # Ensure we iterate over a list of conditions
        if not isinstance(required_when, (list, tuple)):
            required_when = [required_when]

        for condition in required_when:
            # The condition can be a callable
            if callable(condition):
                try:
                    if condition(args):
                        required_names.add(name)
                        break
                except Exception:
                    # If the callable fails, just skip it
                    continue

            # Condition expressed as a tuple/list e.g. (arg_name, expected_value)
            if isinstance(condition, (list, tuple)):
                if len(condition) == 2:
                    cond_arg, cond_value = condition
                    if args.get(cond_arg) == cond_value:
                        required_names.add(name)
                        break
                continue

            # Condition expressed as a dict e.g. {"arg": "mode", "value": "advanced"}
            if isinstance(condition, dict):
                cond_arg = condition.get("arg") or condition.get("name") or condition.get("key")
                cond_value = condition.get("value")
                # Treat missing value as a truthiness check
                if cond_value is not None:
                    if args.get(cond_arg) == cond_value:
                        required_names.add(name)
                        break
                else:
                    # If no explicit value asked, check truthiness
                    if args.get(cond_arg):
                        required_names.add(name)
                        break

    return list(required_names)<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Defensive handling of arguments
    if args is None:
        args = {}
    if options_spec is None:
        return []

    required_args = []
    for opt in options_spec:
        # Skip non-dict items just in case
        if not isinstance(opt, dict):
            continue

        req_when = opt.get("required_when")
        if not req_when:
            continue

        try:
            # If required_when is a callable, invoke it with the args dict
            if callable(req_when):
                matched = bool(req_when(args))
            else:
                # Assume a string expression; evaluate safely with args in context
                # Only expose 'args', no builtins, to keep evaluation safe
                matched = bool(eval(req_when, {}, {"args": args}))
        except Exception:
            # In case of any error evaluating the condition, ignore it
            continue

        if matched:
            # Prefer 'name' field, fallback to 'flag' or 'option'
            opt_name = opt.get("name") or opt.get("flag") or opt.get("option")
            if opt_name:
                required_args.append(opt_name)

    return required_args
