        # The attribute may be named `choices`, `arg_choices`, or `allowed_choices`;
        # fall back to the most common names in order.
        choices_map = (
            getattr(self, "choices", None)
            or getattr(self, "arg_choices", None)
            or getattr(self, "allowed_choices", None)
        )
        if not isinstance(choices_map, dict):
            # No choices defined; nothing to validate.
            return args

        for arg_name, allowed in choices_map.items():
            # Skip validation if the argument is not present in the provided args.
            if arg_name not in args:
                continue

            value = args[arg_name]

            # Normalize the allowed values into a set for O(1) membership checks.
            if isinstance(allowed, (list, tuple, set)):
                allowed_set = set(allowed)
            else:
                # If a single value is specified, treat it as the only allowed option.
                allowed_set = {allowed}

            if value not in allowed_set:
                raise ValueError(
