        if args is None:
            return True
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary of argument names to values")

        # Determine the mapping of argument names to allowed choices.
        # Prefer an attribute named 'choices', fall back to 'available_choices', otherwise assume empty.
        choices_map = getattr(self, "choices", None)
        if choices_map is None:
            choices_map = getattr(self, "available_choices", None)
        if choices_map is None:
            choices_map = {}

        for arg_name, arg_value in args.items():
            # Skip arguments that have no predefined choices.
            if arg_name not in choices_map:
                continue

            allowed = choices_map[arg_name]
            if not isinstance(allowed, (list, tuple, set)):
                # If the allowed choices aren't in a container, treat them as a single valid value.
                allowed = {allowed}

            # Support for iterable values (e.g., list of choices) and single values.
            try:
                if isinstance(arg_value, (list, tuple, set)):
                    invalid = [v for v in arg_value if v not in allowed]
                    if invalid:
                        raise ValueError(
                            f"Argument '{arg_name}' has invalid choice(s): {invalid}. "
                            f"Allowed choices: {list(allowed)}."
                        )
                else:
                    if arg_value not in allowed:
                        raise ValueError(
                            f"Argument '{arg_name}' has invalid choice: {arg_value}. "
                            f"Allowed choices: {list(allowed)}."
                        )
            except TypeError as exc:
                # Handles unhashable types in arg_value or allowed
                raise ValueError(
                    f"Argument '{arg_name}' contains unsupported value types for choice verification."
                ) from exc

        return True<|return|>

def validate_choices_args(self, args):
