        val = args[name]
        # If the allowed value is an iterable (list/set/tuple), check inclusion
        if isinstance(allowed, (list, set, tuple)):
            if val not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{name}': {val!r}. "
                    f"Expected one of {allowed!r}."
