                        f"Validation function for argument '{name}' rejected value {val!r}."
                    )
            except Exception as exc:
                # Wrap any exception from the validator as a ValueError for consistency
                raise ValueError(
                    f"Validator for argument '{name}' raised an exception for value {val!r}."
                ) from exc
        else:
            # Unsupported type in choices_map
            raise TypeError(
                f"Unsupported type for choices of argument '{name}': {type(allowed).__name__}"
            )<|return|>

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        :return: True if all values are within their specified bounds, False otherwise.
        """
        try:
            # Helper to determine if a value is numeric
            def is_numeric(v):
                return isinstance(v, (int, float))

            # Case 1: args is a dict potentially containing multiple argument sets
            if isinstance(args, dict):
                # If top-level dict contains 'min', 'max', and 'value', treat it as a single set
                if {'min', 'max', 'value'}.issubset(args.keys()):
                    min_val = args['min']
                    max_val = args['max']
                    val = args['value']
                    if not (is_numeric(min_val) and is_numeric(max_val) and is_numeric(val)):
                        return False
                    if min_val > max_val:
                        return False
                    return min_val <= val <= max_val

                # Otherwise, iterate over nested dicts assumed to be argument definitions
                for field, definition in args.items():
                    if not isinstance(definition, dict):
                        return False
                    if not {'min', 'max', 'value'}.issubset(definition.keys()):
                        return False
                    min_val = definition['min']
                    max_val = definition['max']
                    val = definition['value']
                    if not (is_numeric(min_val) and is_numeric(max_val) and is_numeric(val)):
                        return False
                    if min_val > max_val:
                        return False
                    if not (min_val <= val <= max_val):
                        return False
                return True

            # Case 2: args is a sequence with [min, max, value]
            if isinstance(args, (list, tuple)) and len(args) == 3:
                min_val, max_val, val = args
                if not (is_numeric(min_val) and is_numeric(max_val) and is_numeric(val)):
                    return False
                if min_val > max_val:
                    return False
                return min_val <= val <= max_val

            # Unsupported format
            return False

        except Exception:
            # Any unexpected error flags validation failure
            return False<|return|>

def validate_min_max_args(self, args):
    """
    Check if the provided argument value is between specified minimum and maximum bounds.

    Supports the following input formats:
      * dict with keys 'value', 'min', and 'max'
      * list or tuple of length 3: (min, max, value)
      * list or tuple of length 2: (min, value) – max is inferred as None and treated as error

    Raises a ValueError if validation fails or if the input format is invalid.
    Returns True if the value is within the bounds.
    """
    try:
        # Extract min, max, and value from the supplied args structure
        if isinstance(args, dict):
            value = args.get('value')
            min_val = args.get('min')
            max_val = args.get('max')
        elif isinstance(args, (list, tuple)):
            if len(args) == 3:
                min_val, max_val, value = args
            elif len(args) == 2:
                # Accept form (min, value) by treating max as None (invalid)
                min_val, value = args
                max_val = None
            else:
                raise ValueError(f"Unexpected number of elements: {len(args)}")
        else:
            raise TypeError(f"Unsupported argument type: {type(args).__name__}")

        # Ensure that min, max, and value are present
        if min_val is None or max_val is None or value is None:
            raise ValueError("Missing 'min', 'max', or 'value' component")

        # Ensure numeric types
        if not all(isinstance(v, (int, float)) for v in (min_val, max_val, value)):
            raise TypeError("All of 'min', 'max', and 'value' must be numeric")

        # Check that min is not greater than max
        if min_val > max_val:
            raise ValueError(f"'min' value {min_val} is greater than 'max' value {max_val}")

        # Validate that the value falls within the inclusive range
        if not (min_val <= value <= max_val):
            raise ValueError(f"Value {value} is not between {min_val} and {max_val}")

        return True

    except Exception as exc:
        raise ValueError(f"Argument validation failed: {exc}") from exc<|return|>

