def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Basic validation of inputs
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")
        if not isinstance(spec_option, dict):
            raise ValueError("spec_option must be a dictionary representing specifications")

        # The complex type can be represented by a simple container object.
        # We define a lightweight class here to encapsulate the details.
        class ComplexType:
            """Container for complex argument type details."""

            def __init__(self, subcommand, type_name, option_name, spec_option):
                self.subcommand = subcommand
                self.type_name = type_name
                self.option_name = option_name
                # Clone spec_option to avoid accidental mutations of the caller's dict
                self.spec_option = dict(spec_option) if spec_option is not None else {}

            def __repr__(self):
                return (f"ComplexType(subcommand={self.subcommand!r}, "
                        f"type_name={self.type_name!r}, "
                        f"option_name={self.option_name!r}, "
                        f"spec_option={self.spec_option!r})")

            def to_dict(self):
                """Return a serialisable representation of the complex type."""
                return {
                    "subcommand": self.subcommand,
                    "type_name": self.type_name,
                    "option_name": self.option_name,
                    "spec_option": self.spec_option,
                }

        # Create and return an instance
        try:
            return ComplexType(subcommand, type_name, option_name, spec_option)
        except Exception as exc:
            # Wrap any unexpected errors in a more descriptive exception
            raise RuntimeError(
                f"Failed to create complex argument type '{type_name}' for "
                f"option '{option_name}' in subcommand '{subcommand}': {exc}"
            ) from exc
