    """
    Split input arguments into control and nested arguments.

    Control arguments are those that influence the behaviour
    of the internal representation and should not be written to
    the spec YAML file.  Nested arguments are the plain key/value
    pairs that should be written into the YAML spec.

    Args
    ----
    args : dict | list
        The collected list of arguments.  It can be given as a
        dictionary, a list of ``(key, value)`` tuples or a list
        of ``key=value`` strings.

    Returns
    -------
    tuple[dict, dict]
        ``(control_args, nested_args)`` – flat dictionaries.
    """
    # Helper to normalise input into a dictionary
    def _as_dict(arg_input):
        if isinstance(arg_input, dict):
            return arg_input
        if isinstance(arg_input, list):
            # List of tuples
            if all(isinstance(item, tuple) and len(item) == 2 for item in arg_input):
                return dict(arg_input)
            # List of key=value strings
            if all(isinstance(item, str) for item in arg_input):
                result = {}
                for item in arg_input:
                    if "=" not in item:
                        continue
                    key, val = item.split("=", 1)
                    result[key.strip()] = val.strip()
                return result
        raise ValueError("Unsupported args format; expected dict or list of tuples/strings")

    try:
        arg_dict = _as_dict(args)
    except Exception as exc:
        raise ValueError(f"Could not interpret args: {exc}") from exc

    # Determine control keys
    control_keys = set()
    if hasattr(self, "CONTROL_ARGS"):
        try:
            control_keys = set(self.CONTROL_ARGS)
        except Exception:
            # Fall back to nothing
            control_keys = set()

    control_args = {}
    nested_args = {}
    for key, value in arg_dict.items():
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args
<|return|>

