    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        The function accepts either a list of strings in the form ``key=value``,
        a mapping or any iterable of key/value pairs and merges them into
        ``vars_dict``. It modifies the original dictionary in place and returns
        it for convenience.

        Parameters
        ----------
        vars_dict : dict
            The dictionary to be extended.
        extra_vars : Iterable | dict | None
            Optional extra variables to merge.

        Returns
        -------
        dict
            The updated dictionary containing the merged entries.
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        if extra_vars is None:
            return vars_dict

        # Normalise extra_vars to an iterable of items
        if isinstance(extra_vars, dict):
            items = list(extra_vars.items())
        elif isinstance(extra_vars, (list, tuple, set)):
            items = list(extra_vars)
        else:
            raise TypeError(
                "extra_vars must be None, a dict, or an iterable of items"
            )

        for item in items:
            if isinstance(item, dict):
                # Merge entire dictionary
                for k, v in item.items():
                    vars_dict[k] = v
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                # Tuple or list of (key, value)
                k, v = item
                vars_dict[k] = v
            elif isinstance(item, str):
                if "=" in item:
                    key, value = item.split("=", 1)
                    vars_dict[key] = value
