    if extra_vars is not None:
        try:
            import json
            json_vars = json.dumps(extra_vars, separators=(',', ':'))
        except Exception:
            json_vars = str(extra_vars)
        cmd += ['--extra-vars', json_vars]

    # Append the playbook path
    cmd.append(playbook_path)

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError:
        raise RuntimeError("`ansible-playbook` command not found. "
                           "Ensure Ansible is installed and in PATH.")
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    # Raise an error if ansible-playbook failed
    if result.returncode != 0:
        err_output = result.stderr.strip() or result.stdout.strip()
        raise RuntimeError(f"Ansible playbook exited with code {result.returncode}:\n{err_output}")

    # Return stdout
