     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import subprocess
    import json

    # Basic validation
    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, bool):
            verbose_level = 1 if verbose else 0
        elif isinstance(verbose, int):
            verbose_level = verbose
        else:
            raise ValueError("verbose must be int or bool")
        if verbose_level < 0 or verbose_level > 5:
            raise ValueError("verbose level must be between 0 and 5")
        cmd.extend([f"-{'v' * verbose_level}" if verbose_level else []])

    # Add ansible_args
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if value is True:
                cmd.append(f"--{key}")
            elif value is False or value is None:
                continue
            else:
                # Use the long form with '=' for clarity
                cmd.append(f"--{key}={value}")

    # Add extra_vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dict")
        # Pass as JSON to handle complex values
        extra_str = json.dumps(extra_vars)
        cmd.extend(["--extra-vars", extra_str])

    # Determine working directory
    cwd = getattr(ir_workspace, "folder", None) or getattr(ir_workspace, "path", None) or os.getcwd()

    # Log the command (assuming ir_plugin has a log method)
    try:
        if hasattr(ir_plugin, "log"):
            ir_plugin.log("Executing: " + " ".join(cmd), level="debug")
    except Exception:
        pass  # ignore any logging errors

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
            check=False,
        )
        output = {
            "returncode": result.returncode,
            "stdout": result.stdout,
            "stderr": result.stderr,
            "success": result.returncode == 0,
        }
    except FileNotFoundError as e:
        output = {
            "returncode": -1,
            "stdout": "",
            "stderr": f"Command not found: {e}",
            "success": False,
        }
    except Exception as exc:
        output = {
            "returncode": -1,
            "stdout": "",
            "stderr": f"Error running ansible-playbook: {exc}",
            "success": False,
        }

    return output
