        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dict")

        # Mapping of parser arguments to desired types.  Extend as needed.
        parsers_info = getattr(self, "_parsers_info", {})
        arg_type_map = parsers_info.get(parser_name, {})

        # Helper to interpret boolean-like strings
        def _to_bool(val):
            trues = {"true", "1", "yes", "y", "on"}
            falses = {"false", "0", "no", "n", "off"}
            val_lower = val.strip().lower()
            if val_lower in trues:
                return True
            if val_lower in falses:
                return False
            raise ValueError(f"cannot convert {val!r} to bool")

        for arg_name, expected_type in arg_type_map.items():
            if arg_name not in values_dict:
                continue
            original = values_dict[arg_name]
            try:
                if expected_type is int:
                    # Reject if string contains non-digit except leading plus/minus
                    if isinstance(original, str) and original.strip().lstrip("+-").isdigit():
                        values_dict[arg_name] = int(original)
                    else:
                        raise ValueError
                elif expected_type is bool:
                    if isinstance(original, str):
                        values_dict[arg_name] = _to_bool(original)
                    else:
                        # Directly cast if bool
                        values_dict[arg_name] = bool(original)
                elif expected_type is list:
                    if isinstance(original, str):
                        # Split on comma, strip whitespace, ignore empty entries
                        values_dict[arg_name] = [item.strip() for item in original.split(",") if item.strip()]
                    elif isinstance(original, (list, tuple)):
                        # Ensure each element is a string
                        values_dict[arg_name] = [str(item) for item in original]
                    else:
                        raise ValueError
                elif expected_type is str:
                    # Force conversion to string
                    values_dict[arg_name] = str(original)
                else:
                    # For any other callable type, attempt to call it
                    values_dict[arg_name] = expected_type(original)
            except Exception as exc:
                # Preserve original string, log warning to stderr
                import sys
                sys.stderr.write(
                    f"Warning: failed to cast argument '{arg_name}' "
                    f"to {expected_type.__name__} (value={original!r}): {exc}\n"
                )
                # Keep the original value unmodified
                continue
        # No return needed; values_dict is mutated in place.<|return|>

