def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        import os
        import json
       from pathlib import Path
    except Exception as e:
        raise RuntimeError(f"Required modules could not be imported: {e}")

    # Validate plugin_dir
    p = Path(plugin_dir)
    if not p.is_dir():
        raise ValueError(f"Provided plugin_dir '{plugin_dir}' is not a directory or does not exist.")

    # Attempt to locate a plugin spec file
    spec_file = None
    # Common names to look for
    possible_names = ['plugin.spec.json', 'plugin.spec.yml', 'plugin.spec.yaml',
                      'plugin.json', 'plugin.yml', 'plugin.yaml']
    for name in possible_names:
        candidate = p / name
        if candidate.is_file():
            spec_file = candidate
            break
    # Fallback: any *.json file in directory
    if spec_file is None:
        json_files = list(p.glob('*.json'))
        if json_files:
            spec_file = json_files[0]

    if spec_file is None or not spec_file.is_file():
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'. Expected one of {possible_names}")

    # Load the spec content
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            content = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON from spec file '{spec_file}': {e}")
    except Exception as e:
        raise RuntimeError(f"Error reading spec file '{spec_file}': {e}")

    # Helper to flatten nested dicts/lists into a flat dict
    def _flatten(item, parent_key=''):
        items = {}
        if isinstance(item, dict):
            for k, v in item.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                items.update(_flatten(v, new_key))
        elif isinstance(item, list):
            for idx, v in enumerate(item):
                new_key = f"{parent_key}[{idx}]" if parent_key else f"[{idx}]"
                items.update(_flatten(v, new_key))
        else:
            items[parent_key] = item
        return items

    flat_dict = _flatten(content)
    return flat_dict

