    spec_filenames = ["plugin.json", "plugin.yml", "plugin.yaml"]
    spec_path = None
    for filename in spec_filenames:
        candidate = os.path.join(plugin_dir, filename)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if not spec_path:
        raise FileNotFoundError("No plugin spec file found (plugin.json, plugin.yml, plugin.yaml) in directory: " + plugin_dir)

    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            if spec_path.endswith('.json'):
                data = json.load(f)
            else:
                try:
                    import yaml
                except ImportError:
                    raise RuntimeError("YAML support not available. Install PyYAML to parse .yml files.")
                data = yaml.safe_load(f)
    except Exception as exc:
