def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec found in the given directory.

    The function searches for a plugin specification file within the directory,
    first looking for YAML files named ``plugin.yaml`` or ``plugin.yml``, and then
    for a JSON file named ``plugin.json``.  Once a file is found, it is parsed
    and the resulting dictionary is flattened: nested keys are joined with
    dots.  Lists are not expanded; they are kept as value objects.

    If the directory does not contain a recognizable spec file or an error
    occurs while reading or parsing the file, an empty dictionary is returned.

    Parameters
    ----------
    plugin_dir : str
        Path to the directory containing the plugin specification file.

    Returns
    -------
    dict
        A flattened dictionary representation of the plugin spec.
    """
    import os
    import json
    try:
        # Find the spec file: priority YAML > JSON
        spec_path = None
        for name in ("plugin.yaml", "plugin.yml", "plugin.json"):
            path = os.path.join(plugin_dir, name)
            if os.path.isfile(path):
                spec_path = path
                break

        if not spec_path:
            return {}

        # Load the spec
        if spec_path.endswith((".yaml", ".yml")):
            import yaml
            with open(spec_path, "r", encoding="utf-8") as f:
                spec_data = yaml.safe_load(f) or {}
        else:  # JSON
            with open(spec_path, "r", encoding="utf-8") as f:
                spec_data = json.load(f)

        if not isinstance(spec_data, dict):
            return {}

        flat_dict = {}

        def _flatten(sub_dict, parent_key=""):
            for key, value in sub_dict.items():
                new_key = f"{parent_key}.{key}" if parent_key else key
                if isinstance(value, dict):
                    _flatten(value, new_key)
                else:
                    flat_dict[new_key] = value

        _flatten(spec_data)
        return flat_dict

    except Exception:
        # In case of any error (file I/O, parsing, etc.) return empty dict
        return {}
