def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate inputs
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings.")
    if root == "":
        raise ValueError("Parameter 'root' cannot be empty.")

    # Leading slash checking
    # The root may or may not end with a slash. For matching we check both cases.
    if path.startswith(root):
        stripped = path[len(root):]
    elif path.startswith(root + "/"):
        stripped = path[len(root) + 1 :]
    elif path.startswith(root + "\\"):
        stripped = path[len(root) + 1 :]
    else:
        raise ValueError(f"Root '{root}' not found in path '{path}'.")

    # Remove any leading path separators from the result
    stripped = stripped.lstrip("/\\")
    if stripped == "":
        raise ValueError("Path becomes empty after stripping root.")
    return stripped<|return|>
